{"file_path":"src/uri.js","content":"/**
 * URI reference parsing, normalization and resolution per RFC 3986,
 * restricted to the rules this program's specification states.
 */

const DEFAULT_PORTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

/** Thrown when a `%` is not followed by two hexadecimal digits. */
export class PercentEncodingError extends Error {
  constructor(component) {
    super(`the ${component} has a truncated percent-encoding`)
    this.component = component
  }
}

/** Thrown when a `resolve` record's base has no scheme. */
export class NoBaseSchemeError extends Error {}

function isHexDigit(ch) {
  return ch !== undefined && /[0-9A-Fa-f]/.test(ch)
}

function isUnreservedChar(ch) {
  return /^[A-Za-z0-9\-._~]$/.test(ch)
}

function asciiLower(s) {
  return s.replace(/[A-Z]/g, (c) => String.fromCharCode(c.charCodeAt(0) + 32))
}

/**
 * Splits a URI reference into its five generic components. Absent
 * components are `null`; a present-but-empty component is `''`. The path
 * is always present, possibly empty.
 */
export function parseReference(s) {
  let rest = s
  let fragment = null
  const hashIdx = rest.indexOf('#')
  if (hashIdx !== -1) {
    fragment = rest.slice(hashIdx + 1)
    rest = rest.slice(0, hashIdx)
  }

  let query = null
  const qIdx = rest.indexOf('?')
  if (qIdx !== -1) {
    query = rest.slice(qIdx + 1)
    rest = rest.slice(0, qIdx)
  }

  let scheme = null
  const colonIdx = rest.indexOf(':')
  if (colonIdx !== -1) {
    const before = rest.slice(0, colonIdx)
    if (!before.includes('/')) {
      scheme = before
      rest = rest.slice(colonIdx + 1)
    }
  }

  let authority = null
  if (rest.startsWith('//')) {
    const afterSlashes = rest.slice(2)
    const slashIdx = afterSlashes.indexOf('/')
    if (slashIdx === -1) {
      authority = afterSlashes
      rest = ''
    } else {
      authority = afterSlashes.slice(0, slashIdx)
      rest = afterSlashes.slice(slashIdx)
    }
  }

  return { scheme, authority, path: rest, query, fragment }
}

/** Splits an authority string into userinfo, host and port. */
function splitAuthority(authority) {
  let userinfo = null
  let rest = authority
  const atIdx = authority.lastIndexOf('@')
  if (atIdx !== -1) {
    userinfo = authority.slice(0, atIdx)
    rest = authority.slice(atIdx + 1)
  }

  const bracketIdx = rest.lastIndexOf(']')
  const searchStart = bracketIdx === -1 ? 0 : bracketIdx + 1
  const colonIdx = rest.indexOf(':', searchStart)
  let host, port
  if (colonIdx !== -1) {
    host = rest.slice(0, colonIdx)
    port = rest.slice(colonIdx + 1)
  } else {
    host = rest
    port = null
  }
  return { userinfo, host, port }
}

function combineAuthority(userinfo, host, port) {
  return (userinfo !== null ? userinfo + '@' : '') + host + (port !== null ? ':' + port : '')
}

function checkPercentEncoding(component, value) {
  if (value === null) return
  for (let i = 0; i < value.length; i++) {
    if (value[i] === '%') {
      if (!isHexDigit(value[i + 1]) || !isHexDigit(value[i + 2])) {
        throw new PercentEncodingError(component)
      }
      i += 2
    }
  }
}

/** Uppercases kept `%XX` hex digits and decodes unreserved ones. Assumes validity. */
function normalizePercentEncoding(value) {
  let out = ''
  for (let i = 0; i < value.length; i++) {
    if (value[i] === '%') {
      const hex = (value[i + 1] + value[i + 2]).toUpperCase()
      const ch = String.fromCharCode(parseInt(hex, 16))
      out += isUnreservedChar(ch) ? ch : '%' + hex
      i += 2
    } else {
      out += value[i]
    }
  }
  return out
}

/** Removes dot segments from a path per RFC 3986 section 5.2.4. */
export function removeDotSegments(path) {
  let input = path
  let output = ''
  while (input.length > 0) {
    if (input.startsWith('../')) {
      input = input.slice(3)
    } else if (input.startsWith('./')) {
      input = input.slice(2)
    } else if (input.startsWith('/./')) {
      input = '/' + input.slice(3)
    } else if (input === '/.') {
      input = '/'
    } else if (input.startsWith('/../')) {
      input = '/' + input.slice(4)
      output = output.slice(0, Math.max(0, output.lastIndexOf('/')))
    } else if (input === '/..') {
      input = '/'
      output = output.slice(0, Math.max(0, output.lastIndexOf('/')))
    } else if (input === '.' || input === '..') {
      input = ''
    } else {
      let idx
      if (input[0] === '/') {
        idx = input.indexOf('/', 1)
      } else {
        idx = input.indexOf('/')
      }
      if (idx === -1) {
        output += input
        input = ''
      } else {
        output += input.slice(0, idx)
        input = input.slice(idx)
      }
    }
  }
  return output
}

/**
 * Applies the full normalization pipeline described by the specification
 * to a set of parsed components, returning a new set of components.
 */
export function normalizeParts(parts) {
  const scheme = parts.scheme !== null ? asciiLower(parts.scheme) : null

  let userinfo = null
  let host = null
  let port = null
  if (parts.authority !== null) {
    const split = splitAuthority(parts.authority)
    userinfo = split.userinfo
    host = split.host
    port = split.port
  }

  // Percent-encoding truncation is reported in this fixed order, regardless
  // of where in the record the offending component actually appears.
  checkPercentEncoding('path', parts.path)
  checkPercentEncoding('userinfo', userinfo)
  checkPercentEncoding('host', host)
  checkPercentEncoding('query', parts.query)
  checkPercentEncoding('fragment', parts.fragment)

  let path = normalizePercentEncoding(parts.path)
  if (userinfo !== null) userinfo = normalizePercentEncoding(userinfo)
  if (host !== null) host = normalizePercentEncoding(host)
  const query = parts.query !== null ? normalizePercentEncoding(parts.query) : null
  const fragment = parts.fragment !== null ? normalizePercentEncoding(parts.fragment) : null

  if (host !== null) host = asciiLower(host)

  if (port !== null && (port === '' || DEFAULT_PORTS[scheme] === port)) {
    port = null
  }

  path = removeDotSegments(path)

  const authority = parts.authority !== null ? combineAuthority(userinfo, host, port) : null
  if (authority !== null && path === '') path = '/'

  return { scheme, authority, path, query, fragment }
}

/** Renders parsed components back into a URI reference string. */
export function serialize(parts) {
  let out = ''
  if (parts.scheme !== null) out += parts.scheme + ':'
  if (parts.authority !== null) out += '//' + parts.authority
  out += parts.path
  if (parts.query !== null) out += '?' + parts.query
  if (parts.fragment !== null) out += '#' + parts.fragment
  return out
}

function mergePaths(base, refPath) {
  if (base.authority !== null && base.path === '') {
    return '/' + refPath
  }
  const idx = base.path.lastIndexOf('/')
  if (idx === -1) return refPath
  return base.path.slice(0, idx + 1) + refPath
}

/**
 * Resolves a reference against a base per RFC 3986 section 5.2.2 (strict),
 * returning the unnormalized target components. Normalization is a
 * separate, final pass applied uniformly regardless of which branch below
 * produced the result.
 */
export function resolveReference(base, ref) {
  if (ref.scheme !== null) {
    return { scheme: ref.scheme, authority: ref.authority, path: ref.path, query: ref.query, fragment: ref.fragment }
  }

  if (ref.authority !== null) {
    return { scheme: base.scheme, authority: ref.authority, path: ref.path, query: ref.query, fragment: ref.fragment }
  }

  if (ref.path === '') {
    return {
      scheme: base.scheme,
      authority: base.authority,
      path: base.path,
      query: ref.query !== null ? ref.query : base.query,
      fragment: ref.fragment,
    }
  }

  const path = ref.path.startsWith('/') ? ref.path : mergePaths(base, ref.path)
  return { scheme: base.scheme, authority: base.authority, path, query: ref.query, fragment: ref.fragment }
}
"}

