{"file_path":"src/lexer.js","content":"/**
 * The scanner. Turns UTF-8 source text into a flat list of tokens, or throws
 * a `ScanError` at the first ill-formed input.
 */

export class ScanError extends Error {
  constructor(line, column, reason) {
    super(`${line}:${column}: ${reason}`)
    this.line = line
    this.column = column
    this.reason = reason
  }
}

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

// Longest match first, so `==` is tried before `=`.
const PUNCTUATION = [
  '==', '!=', '<=', '>=', '&&', '||', '->', '=>',
  '+', '-', '*', '/', '%', '=', '<', '>', '!',
  '(', ')', '{', '}', '[', ']', ',', ';', '.',
]

function isLetter(c) {
  return c !== undefined && /^[A-Za-z]$/.test(c)
}

function isDigit(c) {
  return c !== undefined && c >= '0' && c <= '9'
}

function isHexDigit(c) {
  return c !== undefined && /^[0-9a-fA-F]$/.test(c)
}

function isBinDigit(c) {
  return c === '0' || c === '1'
}

function isOctDigit(c) {
  return c !== undefined && c >= '0' && c <= '7'
}

function isIdentStart(c) {
  return isLetter(c) || c === '_'
}

function isIdentPart(c) {
  return isLetter(c) || isDigit(c) || c === '_'
}

/**
 * Splits `source` into tokens. Each token is
 * `{ kind, text, line, column }`, where `text` is the source text for every
 * kind except `string` and `rawstring`, whose `text` is the decoded value.
 */
export function tokenize(source) {
  const cps = Array.from(source)
  const length = cps.length
  let i = 0
  let line = 1
  let column = 1

  function pos() {
    return { line, column }
  }

  function fail(at, reason) {
    throw new ScanError(at.line, at.column, reason)
  }

  function peek(offset = 0) {
    return cps[i + offset]
  }

  function advance() {
    const c = cps[i++]
    if (c === '\n') {
      line += 1
      column = 1
    } else if (c === '\t') {
      column = (Math.floor((column - 1) / 4) + 1) * 4 + 1
