{"file_path":"src/parser.js","content":"/**
 * Reads the plain-text election format described for the CLI: a
 * `candidates` line naming the field, followed by any number of `ballot`
 * lines. Blank lines and lines beginning with `#` are ignored.
 */

const NAME_RE = /^[A-Za-z0-9_-]+$/
const COUNT_RE = /^[1-9][0-9]*$/

/** Raised for any input that fails to parse; carries the offending line
 * number, or `null` when the failure is not tied to a single line. */
export class ParseError extends Error {
  constructor(line, message) {
    super(message)
    this.line = line
  }
}

/**
 * Parses the election text into `{ candidates, ballots }`, where
 * `candidates` is the declared names in declaration order and each ballot
 * is `{ count, candidates }` with `count` a bigint.
 */
export function parseElection(input) {
  const rawLines = input.split('\n')
  if (rawLines.length > 0 && rawLines[rawLines.length - 1] === '') rawLines.pop()

  const candidateOrder = []
  const candidateSet = new Set()
  const ballots = []
  let sawBallot = false

  for (let i = 0; i < rawLines.length; i++) {
    const lineNo = i + 1
    const trimmed = rawLines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]

    if (directive === 'candidates') {
      if (candidateSet.size > 0 || sawBallot) {
        throw new ParseError(lineNo, 'candidates must be declared once, before any ballot')
      }
      if (tokens.length < 2) {
        throw new ParseError(lineNo, 'expected candidates <name>...')
      }
      for (const name of tokens.slice(1)) {
        if (!NAME_RE.test(name)) throw new ParseError(lineNo, `invalid candidate name ${name}`)
        if (candidateSet.has(name)) throw new ParseError(lineNo, `candidate ${name} is declared twice`)
        candidateSet.add(name)
        candidateOrder.push(name)
      }
    } else if (directive === 'ballot') {
      if (candidateSet.size === 0) {
        throw new ParseError(lineNo, 'candidates must be declared once, before any ballot')
      }
      sawBallot = true
      if (tokens.length < 3) {
        throw new ParseError(lineNo, 'expected ballot <count> <candidate>...')
      }
      const countTok = tokens[1]
      if (!COUNT_RE.test(countTok)) {
        throw new ParseError(lineNo, 'count must be a positive integer')
      }
      const names = tokens.slice(2)
      const seen = new Set()
      for (const name of names) {
        if (!candidateSet.has(name)) throw new ParseError(lineNo, `unknown candidate ${name}`)
        if (seen.has(name)) throw new ParseError(lineNo, `candidate ${name} is repeated`)
        seen.add(name)
      }
      ballots.push({ count: BigInt(countTok), candidates: names })
    } else {
      throw new ParseError(lineNo, `unknown directive ${directive}`)
    }
  }

  if (candidateSet.size === 0) {
    throw new ParseError(null, 'no candidates')
  }

  return { candidates: candidateOrder, ballots }
}
"}

