{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */

import { parseElection, ParseError } from './parser.js'
import { runElection } from './election.js'

function formatRound(number, tally, exhausted) {
  const entries = [...tally.entries()]
  entries.sort(([nameA, votesA], [nameB, votesB]) => {
    if (votesA !== votesB) return votesA > votesB ? -1 : 1
    return nameA < nameB ? -1 : nameA > nameB ? 1 : 0
  })
  const parts = entries.map(([name, votes]) => `${name}=${votes}`)
  return `round ${number}: ${parts.join(' ')} exhausted=${exhausted}`
}

async function readStdin() {
  process.stdin.setEncoding('utf8')
  let input = ''
  for await (const chunk of process.stdin) input += chunk
  return input
}

async function main() {
  const mode = process.argv[2]
  if (mode !== 'rounds' && mode !== 'tally') {
    process.stderr.write('error: usage: cli.js rounds|tally\n')
    process.exit(2)
  }

  const input = await readStdin()

  let election
  try {
    election = parseElection(input)
  } catch (err) {
    if (!(err instanceof ParseError)) throw err
    const prefix = err.line === null ? 'error: ' : `error: line ${err.line}: `
    process.stderr.write(`${prefix}${err.message}\n`)
    process.exit(2)
  }

  const result = runElection(election)

  const lines = []
  if (mode === 'rounds') {
    result.rounds.forEach((round, index) => {
      lines.push(formatRound(index + 1, round.tally, round.exhausted))
      if (round.eliminated !== null) lines.push(`eliminated ${round.eliminated}`)
    })
  } else {
    lines.push(`rounds ${result.roundCount}`)
  }
  lines.push(result.winner === null ? 'no winner' : `winner ${result.winner}`)

  process.stdout.write(`${lines.join('\n')}\n`)
}

main()
"}

