 */
export function setting(key) {
  return BY_KEY.get(key)
}

const DURATION = /^([0-9]+)(ms|s|m|h)$/
const DURATION_FACTOR = { ms: 1n, s: 1000n, m: 60000n, h: 3600000n }
const INTEGER = /^-?(0|[1-9][0-9]*)$/

/**
 * Coerce one setting's raw text by its declared type.
 * @param {{key: string, type: string, members?: string[]}} declared - the setting, as `setting()` returns.
 * @param {string} text - the raw text a layer wrote, or the schema default.
 * @returns {string} the text to render: as written, for every type but `duration`, which renders as milliseconds.
 * @throws {Error} `<key> is not a(n) <type>: <text>`, `<key> is not one of <members>: <text>`,
 *   or `<key> has an empty item: <text>`, when the text does not fit the declared type.
 */
export function coerce(declared, text) {
  switch (declared.type) {
    case 'string':
      return text
    case 'integer':
      if (!INTEGER.test(text)) throw new Error(`${declared.key} is not an integer: ${text}`)
      return text
    case 'boolean':
      if (text !== 'true' && text !== 'false') throw new Error(`${declared.key} is not a boolean: ${text}`)
      return text
    case 'enum':
      if (!declared.members.includes(text)) {
        throw new Error(`${declared.key} is not one of ${declared.members.join('|')}: ${text}`)
      }
      return text
    case 'duration': {
      const match = DURATION.exec(text)
      if (!match) throw new Error(`${declared.key} is not a duration: ${text}`)
      return (BigInt(match[1]) * DURATION_FACTOR[match[2]]).toString()
    }
    case 'list': {
      if (text === '') return ''
      const items = text.split(',').map(item => item.trim())
      if (items.some(item => item === '')) throw new Error(`${declared.key} has an empty item: ${text}`)
      const seen = new Set()
      const deduped = []
      for (const item of items) {
        if (!seen.has(item)) {
          seen.add(item)
          deduped.push(item)
        }
      }
      return deduped.join(',')
    }
    default:
      throw new Error(`unknown type ${declared.type}`)
  }
}"}

