{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/** The command: `html`, `outline`, and `defs`, each over the document on standard input. */

import { readFileSync } from 'node:fs'
import { BlockError, DEFINITION_LINE, headings, parse, render, splitLines } from './block.js'
import { normalizeLabel } from './labels.js'

const USAGE = 'usage: cli.js html|outline|defs [<definitions>]'

/** Report one failure the way the specification words it, and stop. */
function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

const argv = process.argv.slice(2)
const mode = argv[0]
if (!['html', 'outline', 'defs'].includes(mode) || argv.length < 1 || argv.length > 2) fail(USAGE)

const defsPath = argv[1]
const fileDefinitions = new Map()
if (defsPath !== undefined) {
  let text
  try {
    text = readFileSync(defsPath, 'utf8')
  } catch {
    fail(`cannot read definitions ${defsPath}`)
  }
  const lines = splitLines(text)
  for (let index = 0; index < lines.length; index += 1) {
    const trimmed = lines[index].trim()
    const number = index + 1
    if (trimmed === '' || trimmed.startsWith('#')) continue
    const match = DEFINITION_LINE.exec(trimmed)
    if (match === null) fail(`${defsPath}: line ${number}: expected [label]: <url>`)
    const label = normalizeLabel(match[1])
    if (fileDefinitions.has(label)) fail(`${defsPath}: line ${number}: label ${label} is defined twice`)
    fileDefinitions.set(label, match[2])
  }
}

let parsed
try {
  parsed = parse(splitLines(readFileSync(0, 'utf8')), new Set(fileDefinitions.keys()))
} catch (error) {
  if (!(error instanceof BlockError)) throw error
  fail(`line ${error.line}: ${error.message}`)
}

const definitions = new Map([...fileDefinitions, ...parsed.definitions])

if (mode === 'html') {
  process.stdout.write(render(parsed.blocks, definitions))
} else if (mode === 'outline') {
  process.stdout.write(headings(parsed.blocks).map(one => `${one.level} ${one.text}\n`).join(''))
} else {
  const rows = [
    ...[...fileDefinitions].map(([label, url]) => ({ label, url, source: 'file' })),
    ...[...parsed.definitions].map(([label, url]) => ({ label, url, source: 'document' })),
  ].sort((a, b) => (a.label < b.label ? -1 : a.label > b.label ? 1 : 0))
  process.stdout.write(rows.map(row => `${row.label} ${row.url} ${row.source}\n`).join(''))
  process.stdout.write(`total ${rows.length}\n`)
}
"}

