{"file_path":"src/parse.js","content":"/**
 * Parsing of the build-graph text format read from standard input.
 *
 * The result is a `Graph`: a map of task name to cost, and a map of task
 * name to the set of names it depends on. Any malformed input throws a
 * `CliError` carrying the exit code and the message body cli.js writes
 * after the `error: ` prefix.
 */

const NAME_PATTERN = /^[A-Za-z0-9_.-]+$/
const COST_PATTERN = /^[0-9]+$/

export class CliError extends Error {
  constructor(exitCode, body) {
    super(body)
    this.exitCode = exitCode
  }
}

function lineError(lineNo, detail) {
  return new CliError(2, `line ${lineNo}: ${detail}`)
}

/**
 * Splits stdin into the lines the format is defined over, dropping the
 * single empty entry a trailing newline leaves after `split('\n')`.
 */
function splitLines(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

/**
 * Parses the raw text into a graph, or throws a `CliError` for the first
 * malformed line, unknown task reference, or duplicate declaration.
 */
export function parseGraph(input) {
  const lines = splitLines(input)
  const tasks = new Map() // name -> cost
  const depEdges = [] // { line, name, deps: [names in input order] }, in encounter order

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) throw lineError(lineNo, 'expected task <name> <cost>')
      const [, name, costText] = words
      if (!NAME_PATTERN.test(name)) throw lineError(lineNo, `invalid task name ${name}`)
      if (!COST_PATTERN.test(costText)) throw lineError(lineNo, 'cost must be a non-negative integer')
      if (tasks.has(name)) throw lineError(lineNo, `task ${name} is declared twice`)
      tasks.set(name, parseInt(costText, 10))
    } else if (directive === 'dep') {
      if (words.length < 3) throw lineError(lineNo, 'expected dep <name> <dependency>...')
      const [, name, ...deps] = words
      depEdges.push({ line: lineNo, name, deps })
    } else {
      throw lineError(lineNo, `unknown directive ${directive}`)
    }
  }

  for (const edge of depEdges) {
    if (!tasks.has(edge.name)) throw new CliError(2, `unknown task ${edge.name}`)
    for (const dep of edge.deps) {
      if (!tasks.has(dep)) throw new CliError(2, `unknown task ${dep}`)
    }
  }

  const deps = new Map()
  for (const name of tasks.keys()) deps.set(name, new Set())
  for (const edge of depEdges) {
    const set = deps.get(edge.name)
    for (const dep of edge.deps) set.add(dep)
  }

  return { tasks, deps }
}

/**
 * Finds the first cycle a depth-first search encounters when it visits
 * tasks in ascending name order and, from each task, its dependencies in
 * ascending name order. Returns the cycle as an array of names starting
 * and ending with the re-entered task, or `null` when the graph is acyclic.
 */
export function findCycle(graph) {
  const { tasks, deps } = graph
  const names = [...tasks.keys()].sort()
  const UNVISITED = 0
  const ON_STACK = 1
  const DONE = 2
  const state = new Map()
  const stack = []

  function visit(node) {
    state.set(node, ON_STACK)
    stack.push(node)
    const neighbors = [...deps.get(node)].sort()
    for (const neighbor of neighbors) {
      const neighborState = state.get(neighbor) ?? UNVISITED
      if (neighborState === ON_STACK) {
        const start = stack.indexOf(neighbor)
        return stack.slice(start).concat(neighbor)
      }
      if (neighborState === UNVISITED) {
        const found = visit(neighbor)
        if (found) return found
      }
    }
    state.set(node, DONE)
    stack.pop()
    return null
  }

  for (const name of names) {
    if ((state.get(name) ?? UNVISITED) === UNVISITED) {
      const found = visit(name)
      if (found) return found
    }
  }
  return null
}
"}

