{"file_path":"src/diff.js","content":"/**
 * Computes the changes needed to turn `base` into `side`, using a longest
 * common subsequence over whole lines (compared as exact strings).
 *
 * When several subsequences share the maximum length, the one reconstructed
 * here is the one whose matches occur earliest: walking both documents from
 * the start, a match is taken whenever the current lines are equal;
 * otherwise the side whose remaining subsequence is at least as long as the
 * other's is advanced, with base preferred on a tie.
 *
 * Returns a list of changes ordered by base position, each describing a run
 * of base lines (`start` to `end`, `end` exclusive) replaced by a run of the
 * side's lines (`lines`). An insertion has `start === end`; a deletion has
 * an empty `lines` array.
 */
export function diffAgainstBase(base, side) {
  const m = base.length
  const n = side.length

  // dp[i][j] holds the LCS length of base[i:] and side[j:], stored as a
  // flat (m+1) x (n+1) array with row stride n+1.
  const stride = n + 1
  const dp = new Uint32Array((m + 1) * stride)
  for (let i = m - 1; i >= 0; i--) {
    for (let j = n - 1; j >= 0; j--) {
      const here = i * stride + j
      if (base[i] === side[j]) {
        dp[here] = dp[(i + 1) * stride + (j + 1)] + 1
      } else {
        const dropBase = dp[(i + 1) * stride + j]
        const dropSide = dp[i * stride + (j + 1)]
        dp[here] = dropBase >= dropSide ? dropBase : dropSide
      }
    }
  }

  const changes = []
  let runStart = null
  let runLines = []
  let i = 0
  let j = 0

  const flush = end => {
    if (runStart !== null) {
      changes.push({ start: runStart, end, lines: runLines })
      runStart = null
      runLines = []
    }
  }

  while (i < m || j < n) {
    if (i < m && j < n && base[i] === side[j]) {
      flush(i)
      i++
      j++
      continue
    }
    if (runStart === null) runStart = i
    let advanceBase
    if (j >= n) advanceBase = true
    else if (i >= m) advanceBase = false
    else advanceBase = dp[(i + 1) * stride + j] >= dp[i * stride + (j + 1)]
    if (advanceBase) {
      i++
    } else {
      runLines.push(side[j])
      j++
    }
  }
  flush(i)

  return changes
}
"}

