{"file_path":"src/regions.js","content":"import { diffAgainstBase } from './diff.js'

function arraysEqual(a, b) {
  if (a.length !== b.length) return false
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return false
  return true
}

/**
 * Builds the side's version of a region: base lines this side left
 * untouched, interleaved with the lines from this side's changes that
 * touch the region.
 */
function sideLinesForRegion(base, changes, start, end) {
  const lines = []
  let cursor = start
  for (const change of changes) {
    for (let k = cursor; k < change.start; k++) lines.push(base[k])
    for (const line of change.lines) lines.push(line)
    cursor = change.end
  }
  for (let k = cursor; k < end; k++) lines.push(base[k])
  return lines
}

/**
 * Splits `base`, `mine` and `theirs` into an ordered list of regions.
 *
 * A stable region is `{ kind: 'stable', lines }` for a stretch of base
 * lines neither side touched. A touched region is
 * `{ kind: 'mine' | 'theirs' | 'both', lines }` when the sides agree on the
 * resolution, or `{ kind: 'conflict', mine, base, theirs }` when they don't.
 */
export function buildRegions(mine, base, theirs) {
  const mineChanges = diffAgainstBase(base, mine).map(change => ({ ...change, side: 'mine' }))
  const theirsChanges = diffAgainstBase(base, theirs).map(change => ({ ...change, side: 'theirs' }))

  const allChanges = [...mineChanges, ...theirsChanges].sort((a, b) => {
    if (a.start !== b.start) return a.start - b.start
    if (a.side === b.side) return 0
    return a.side === 'mine' ? -1 : 1
  })

  const regions = []
  let cursor = 0
  let idx = 0
  while (idx < allChanges.length) {
    const touching = [allChanges[idx]]
    let regionStart = allChanges[idx].start
    let regionEnd = allChanges[idx].end
    idx++
    while (idx < allChanges.length && allChanges[idx].start <= regionEnd) {
      regionEnd = Math.max(regionEnd, allChanges[idx].end)
      touching.push(allChanges[idx])
      idx++
    }

    if (regionStart > cursor) {
      regions.push({ kind: 'stable', lines: base.slice(cursor, regionStart) })
    }

    const mineTouching = touching.filter(c => c.side === 'mine')
    const theirsTouching = touching.filter(c => c.side === 'theirs')
    const mineLines = sideLinesForRegion(base, mineTouching, regionStart, regionEnd)
    const theirsLines = sideLinesForRegion(base, theirsTouching, regionStart, regionEnd)
    const baseLines = base.slice(regionStart, regionEnd)

    if (arraysEqual(mineLines, theirsLines)) {
      regions.push({ kind: 'both', lines: mineLines })
    } else if (arraysEqual(mineLines, baseLines)) {
      regions.push({ kind: 'theirs', lines: theirsLines })
    } else if (arraysEqual(theirsLines, baseLines)) {
      regions.push({ kind: 'mine', lines: mineLines })
    } else {
      regions.push({ kind: 'conflict', mine: mineLines, base: baseLines, theirs: theirsLines })
    }

    cursor = regionEnd
  }

  if (cursor < base.length) {
    regions.push({ kind: 'stable', lines: base.slice(cursor) })
  }

  return regions
}
"}

