{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */

import { readFileSync } from 'node:fs'
import { buildRegions } from './regions.js'

const MODES = new Set(['merge', 'merge2', 'regions'])

function fail(message) {
  process.stderr.write(`${message}\n`)
  process.exit(2)
}

function parseDocuments(input) {
  let lines = input.length === 0 ? [] : input.split('\n')
  if (input.endsWith('\n')) lines.pop()

  const parts = [[]]
  for (const line of lines) {
    if (line === '%%%') parts.push([])
    else parts[parts.length - 1].push(line)
  }
  if (parts.length !== 3) fail('error: expected three parts separated by %%%')
  return parts
}

function main() {
  if (process.argv.length !== 3 || !MODES.has(process.argv[2])) {
    fail('error: usage: cli.js merge|merge2|regions')
  }
  const mode = process.argv[2]

  const input = readFileSync(0, 'utf8')
  const [mine, base, theirs] = parseDocuments(input)

  const regions = buildRegions(mine, base, theirs)
  const hasConflict = regions.some(region => region.kind === 'conflict')

  const out = []
  if (mode === 'regions') {
    for (const region of regions) {
      if (region.kind === 'conflict') {
        out.push(`conflict mine=${region.mine.length} base=${region.base.length} theirs=${region.theirs.length}`)
      } else {
        out.push(`${region.kind} ${region.lines.length}`)
      }
    }
  } else {
    const withBase = mode === 'merge'
    for (const region of regions) {
      if (region.kind === 'conflict') {
        out.push('<<<<<<< mine')
        out.push(...region.mine)
        if (withBase) {
          out.push('||||||| base')
          out.push(...region.base)
        }
        out.push('=======')
        out.push(...region.theirs)
        out.push('>>>>>>> theirs')
      } else {
        out.push(...region.lines)
      }
    }
  }

  process.stdout.write(out.map(line => `${line}\n`).join(''))
  process.exit(hasConflict ? 1 : 0)
}

main()
"}

