{"file_path":"src/engine.js","content":"/**
 * Replays a parsed limiter file's events against its policies, producing one
 * verdict per event in log order.
 */

/**
 * Finds the route whose prefix is longest among those that start `key`,
 * or `null` when no route matches.
 */
function matchRoute(routes, routeOrder, key) {
  let best = null
  for (const prefix of routeOrder) {
    if (key.startsWith(prefix) && (best === null || prefix.length > best.length)) {
      best = prefix
    }
  }
  return best === null ? null : routes.get(best)
}

export function replay({ policies, routes, routeOrder, events }) {
  const verdicts = []
  for (const { tick, key } of events) {
    const policyNames = matchRoute(routes, routeOrder, key)
    if (policyNames === null) {
      verdicts.push({ tick, key, allow: true, policy: null })
      continue
    }

    const instances = policyNames.map((name) => policies.get(name))
    for (const policy of instances) policy.advance(key, tick)

    let deniedBy = null
    for (let i = 0; i < instances.length; i++) {
      if (!instances[i].allowed(key)) {
        deniedBy = policyNames[i]
        break
      }
    }

    if (deniedBy === null) {
      for (const policy of instances) policy.record(key, tick)
      verdicts.push({ tick, key, allow: true, policy: null })
    } else {
      verdicts.push({ tick, key, allow: false, policy: deniedBy })
    }
  }
  return verdicts
}
"}

{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */
import { readFileSync } from 'node:fs'
import { parse } from './parser.js'
import { replay } from './engine.js'
import { LimiterError } from './errors.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'replay' && args[0] !== 'summary')) {
    fail('usage: cli.js replay|summary')
  }
  const mode = args[0]

  const input = readFileSync(0, 'utf8')

  let parsed
  try {
    parsed = parse(input)
  } catch (err) {
    if (err instanceof LimiterError) fail(err.message)
    throw err
  }

  const verdicts = replay(parsed)

  if (mode === 'replay') {
    const lines = verdicts.map((v) =>
      v.allow ? `${v.tick} ${v.key} allow` : `${v.tick} ${v.key} deny ${v.policy}`
    )
    process.stdout.write(lines.length > 0 ? lines.join('\n') + '\n' : '')
    return
  }

  const totals = new Map()
  for (const { key, allow } of verdicts) {
    let t = totals.get(key)
    if (!t) {
      t = { allowed: 0, denied: 0 }
      totals.set(key, t)
    }
    if (allow) t.allowed++
    else t.denied++
  }

  const lines = []
  let totalAllowed = 0
  let totalDenied = 0
  for (const key of [...totals.keys()].sort()) {
    const t = totals.get(key)
    lines.push(`${key} allowed=${t.allowed} denied=${t.denied}`)
    totalAllowed += t.allowed
    totalDenied += t.denied
  }
  lines.push(`total allowed=${totalAllowed} denied=${totalDenied}`)
  process.stdout.write(lines.join('\n') + '\n')
}

main()
"}

