 * Turns a parsed document tree (see `nodes.js`) into the `json` or `keys`
 * output formats.
 */
import { typeName } from './nodes.js'

function sortedKeys(table) {
  return [...table.entries.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
}

function renderNode(node, indent) {
  const pad = '  '.repeat(indent)
  const padIn = '  '.repeat(indent + 1)
  switch (node.kind) {
    case 'table': {
      const keys = sortedKeys(node)
      if (keys.length === 0) return '{}'
      const lines = keys.map(
        (key) => `${padIn}${JSON.stringify(key)}: ${renderNode(node.entries.get(key), indent + 1)}`,
      )
      return `{\n${lines.join(',\n')}\n${pad}}`
    }
    case 'arrayOfTables':
    case 'array': {
      const items = node.items
      if (items.length === 0) return '[]'
      const lines = items.map((item) => `${padIn}${renderNode(item, indent + 1)}`)
      return `[\n${lines.join(',\n')}\n${pad}]`
    }
    case 'string':
      return JSON.stringify(node.value)
    case 'integer':
      return String(node.value)
    case 'float':
      return JSON.stringify(node.value)
    case 'boolean':
      return node.value ? 'true' : 'false'
    default:
      throw new Error(`unreachable node kind ${node.kind}`)
  }
}

export function renderJson(root) {
  return `${renderNode(root, 0)}\n`
}

function walkKeys(node, path, out) {
  if (node.kind === 'table') {
    for (const key of sortedKeys(node)) {
      const child = node.entries.get(key)
      const childPath = path === '' ? key : `${path}.${key}`
      out.push(`${childPath} ${typeName(child)}`)
      walkKeys(child, childPath, out)
    }
  } else if (node.kind === 'array' || node.kind === 'arrayOfTables') {
    node.items.forEach((item, index) => {
      const childPath = `${path}[${index}]`
      out.push(`${childPath} ${typeName(item)}`)
      walkKeys(item, childPath, out)
    })
  }
}

export function renderKeys(root) {
  const out = []
  walkKeys(root, '', out)
  return out.length === 0 ? '' : `${out.join('\n')}\n`
}
"}

