/** Thrown for any formula the grammar does not accept. */
export class ParseError extends Error {}

const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])
const ADDITIVE_OPS = new Set(['+', '-'])
const MULTIPLICATIVE_OPS = new Set(['*', '/'])

class Cursor {
  constructor(tokens) {
    this.tokens = tokens
    this.pos = 0
  }
  peek() {
    return this.tokens[this.pos]
  }
  next() {
    return this.tokens[this.pos++]
  }
  expect(type) {
    const t = this.next()
    if (!t || t.type !== type) throw new ParseError(`expected ${type}`)
    return t
  }
}

function parseComparison(cur) {
  let left = parseAdditive(cur)
  while (cur.peek() && COMPARISON_OPS.has(cur.peek().type)) {
    const op = cur.next().type
    const right = parseAdditive(cur)
    left = { type: 'Binary', op, left, right }
  }
  return left
}

function parseAdditive(cur) {
  let left = parseMultiplicative(cur)
  while (cur.peek() && ADDITIVE_OPS.has(cur.peek().type)) {
    const op = cur.next().type
    const right = parseMultiplicative(cur)
    left = { type: 'Binary', op, left, right }
  }
  return left
}

function parseMultiplicative(cur) {
  let left = parsePower(cur)
  while (cur.peek() && MULTIPLICATIVE_OPS.has(cur.peek().type)) {
    const op = cur.next().type
    const right = parsePower(cur)
    left = { type: 'Binary', op, left, right }
  }
  return left
}

function parsePower(cur) {
  const left = parseUnary(cur)
  if (cur.peek() && cur.peek().type === '^') {
    cur.next()
    const right = parsePower(cur)
    return { type: 'Binary', op: '^', left, right }
  }
  return left
}

function parseUnary(cur) {
  const t = cur.peek()
  if (t && (t.type === '+' || t.type === '-')) {
    cur.next()
    const operand = parseUnary(cur)
    return { type: 'Unary', op: t.type, operand }
  }
  return parsePrimary(cur)
}

function parsePrimary(cur) {
  const t = cur.next()
  if (!t) throw new ParseError('unexpected end of formula')
  if (t.type === 'NUMBER') return { type: 'Number', value: parseFloat(t.text) }
  if (t.type === '(') {
    const expr = parseComparison(cur)
    cur.expect(')')
    return { type: 'Paren', expr }
  }
  if (t.type === 'WORD') {
    const next = cur.peek()
    if (next && next.type === '(') {
      cur.next()
      const args = []
      if (cur.peek() && cur.peek().type !== ')') {
        args.push(parseComparison(cur))
        while (cur.peek() && cur.peek().type === ',') {
          cur.next()
          args.push(parseComparison(cur))
        }
      }
      cur.expect(')')
      return { type: 'Call', name: t.text.toUpperCase(), args }
    }
    if (next && next.type === ':') {
      cur.next()
      const w2 = cur.expect('WORD')
      return { type: 'Range', from: t.text.toUpperCase(), to: w2.text.toUpperCase() }
    }
    const upper = t.text.toUpperCase()
    if (upper === 'TRUE') return { type: 'Bool', value: true }
    if (upper === 'FALSE') return { type: 'Bool', value: false }
    return { type: 'Address', word: upper }
  }
  throw new ParseError(`unexpected token ${t.text}`)
}

/** Parse a formula body (without the leading `=`) into an AST, or throw ParseError/LexError. */
export function parseFormula(body) {
  const tokens = tokenize(body)
  const cur = new Cursor(tokens)
  const ast = parseComparison(cur)
  if (cur.peek() !== undefined) throw new ParseError('trailing tokens')
  return ast
}

export { LexError }
"}

