/**
 * Collect every distinct addressable cell an AST names directly, ranges
 * expanded, regardless of where in the tree it sits (a misplaced range still
 * names every cell it covers).
 */
export function collectDeps(node, out) {
  if (!node) return
  switch (node.type) {
    case 'Number':
    case 'Bool':
      return
    case 'Paren':
      collectDeps(node.expr, out)
      return
    case 'Unary':
      collectDeps(node.operand, out)
      return
    case 'Binary':
      collectDeps(node.left, out)
      collectDeps(node.right, out)
      return
    case 'Address': {
      const info = parseAddressWord(node.word)
      if (info.valid) out.add(info.col + info.row)
      return
    }
    case 'Range': {
      const cells = resolveRangeCells(node.from, node.to)
      if (cells) for (const c of cells) out.add(c)
      return
    }
    case 'Call':
      for (const arg of node.args) collectDeps(arg, out)
      return
    default:
      return
  }
}
"}

