import { parseFormula, ParseError } from './parser.js'
import { LexError } from './lexer.js'
import { NUM, TEXT, BOOL, ERR, parseLiteral, toNumberOrErr } from './value.js'

const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])
const LIST_FUNCTIONS = new Set(['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'])

/** Signals that evaluating `addr` looped back into a cell already being evaluated. */
class CycleSignal {
  constructor(addr) {
    this.addr = addr
  }
}

/** Evaluates every cell of a sheet, memoizing values and detecting cycles. */
export class Evaluator {
  constructor(cells) {
    this.cells = cells
    this.cache = new Map()
    this.visiting = new Set()
    this.asts = new Map()
  }

  /** Parse (and cache) the formula AST for a cell's content, or null if it is not a formula. */
  getAst(content) {
    if (this.asts.has(content)) return this.asts.get(content)
    let ast = null
    if (content.startsWith('=')) {
      try {
        ast = parseFormula(content.slice(1))
      } catch (e) {
        if (e instanceof ParseError || e instanceof LexError) ast = 'invalid'
        else throw e
      }
    }
    this.asts.set(content, ast)
    return ast
  }

  /** Evaluate the cell at `key`, using and populating the shared cache. */
  getCellValue(key) {
    if (this.cache.has(key)) return this.cache.get(key)
    if (this.visiting.has(key)) throw new CycleSignal(key)
    const content = this.cells.has(key) ? this.cells.get(key) : ''
    this.visiting.add(key)
    try {
      let value
      if (content.startsWith('=')) {
        const ast = this.getAst(content)
        value = ast === 'invalid' ? ERR('#ERR!') : this.evalNode(ast)
      } else {
        value = parseLiteral(content)
      }
      this.cache.set(key, value)
      return value
    } catch (e) {
      if (e instanceof CycleSignal) {
        const cyc = ERR('#CYCLE!')
        this.cache.set(key, cyc)
        if (e.addr !== key) throw e
        return cyc
      }
      throw e
    } finally {
      this.visiting.delete(key)
    }
  }

  evalNode(node) {
    switch (node.type) {
      case 'Number':
        return NUM(node.value)
      case 'Bool':
        return BOOL(node.value)
      case 'Paren':
        return this.evalNode(node.expr)
      case 'Range':
        return ERR('#ERR!')
      case 'Address': {
        const info = parseAddressWord(node.word)
        if (!info.valid) return ERR('#REF!')
        return this.getCellValue(info.col + info.row)
      }
      case 'Unary':
        return this.evalUnary(node)
      case 'Binary':
        return this.evalBinary(node)
      case 'Call':
        return this.evalCall(node)
      default:
        return ERR('#ERR!')
    }
  }

  evalUnary(node) {
    const v = this.evalNode(node.operand)
    if (v.t === 'err') return v
    const n = toNumberOrErr(v)
    if (n.t === 'err') return n
    const result = node.op === '-' ? -n.v : n.v
    return finiteOrDivZero(result)
  }

  evalBinary(node) {
    const l = this.evalNode(node.left)
    if (l.t === 'err') return l
    const r = this.evalNode(node.right)
    if (r.t === 'err') return r
    if (COMPARISON_OPS.has(node.op)) return compareOp(node.op, l, r)
    const ln = toNumberOrErr(l)
    if (ln.t === 'err') return ln
    const rn = toNumberOrErr(r)
    if (rn.t === 'err') return rn
    return arithmeticOp(node.op, ln.v, rn.v)
  }

  /** Expand one call argument node into its flat list of raw Values (ranges expanded). */
  expandArg(node) {
    if (node.type === 'Range') {
      const cells = resolveRangeCells(node.from, node.to)
      if (!cells) return [ERR('#REF!')]
      return cells.map((key) => this.getCellValue(key))
    }
    return [this.evalNode(node)]
  }

  evalCall(node) {
    const fn = node.name
    if (fn === 'IF') {
      if (node.args.length !== 3) return ERR('#ERR!')
      const cond = this.evalNode(node.args[0])
      if (cond.t === 'err') return cond
      let truthy
      if (cond.t === 'bool') truthy = cond.v
      else if (cond.t === 'num') truthy = cond.v !== 0
      else return ERR('#VALUE!')
      return this.evalNode(node.args[truthy ? 1 : 2])
    }
    if (fn === 'ABS') {
      if (node.args.length !== 1) return ERR('#ERR!')
      const v = this.evalNode(node.args[0])
      if (v.t === 'err') return v
      const n = toNumberOrErr(v)
      if (n.t === 'err') return n
      return finiteOrDivZero(Math.abs(n.v))
    }
    if (LIST_FUNCTIONS.has(fn)) {
