      const raw = []
      for (const arg of node.args) raw.push(...this.expandArg(arg))
      if (fn === 'COUNT') {
        const firstErr = raw.find((v) => v.t === 'err')
        if (firstErr) return firstErr
        return NUM(raw.filter((v) => v.t === 'num').length)
      }
      const nums = []
      let firstErr = null
