{"file_path":"src/diff3.js","content":"/**
 * Core three-way merge logic: diffing each side against the base, grouping
 * the resulting changes into regions, and resolving each region.
 */

/**
 * Compute dp[i][j] = length of the longest common subsequence of
 * base[i:] and side[j:], for every i in [0, base.length] and every
 * j in [0, side.length].
 */
function suffixLcsLengths(base, side) {
  const m = base.length
  const n = side.length
  const dp = new Array(m + 1)
  for (let i = 0; i <= m; i++) dp[i] = new Array(n + 1).fill(0)
  for (let i = m - 1; i >= 0; i--) {
    for (let j = n - 1; j >= 0; j--) {
      if (base[i] === side[j]) dp[i][j] = dp[i + 1][j + 1] + 1
      else dp[i][j] = Math.max(dp[i + 1][j], dp[i][j + 1])
    }
  }
  return dp
}

/**
 * Walk base and side from the start, taking a match whenever the current
 * lines are equal and otherwise advancing whichever side keeps at least as
 * long a remaining common subsequence available, preferring to advance the
 * base on a tie. Returns the list of matched [baseIndex, sideIndex] pairs.
 */
function alignForward(base, side, dp) {
  const matches = []
  let i = 0
  let j = 0
  while (i < base.length && j < side.length) {
    if (base[i] === side[j]) {
      matches.push([i, j])
      i++
      j++
    } else if (dp[i + 1][j] >= dp[i][j + 1]) {
      i++
    } else {
      j++
    }
  }
  return matches
}

/**
 * Diff a side against the base: every stretch the alignment does not cover
 * becomes a change, a run of base lines replaced by a run of the side's
 * lines.
 */
export function diffAgainstBase(base, side) {
  const dp = suffixLcsLengths(base, side)
  const matches = alignForward(base, side, dp)
  const changes = []
  let baseCursor = 0
  let sideCursor = 0
  for (const [bi, si] of matches) {
    if (bi > baseCursor || si > sideCursor) {
      changes.push({
        baseStart: baseCursor,
        baseEnd: bi,
        sideStart: sideCursor,
        sideEnd: si,
      })
    }
    baseCursor = bi + 1
    sideCursor = si + 1
  }
  if (baseCursor < base.length || sideCursor < side.length) {
    changes.push({
      baseStart: baseCursor,
      baseEnd: base.length,
      sideStart: sideCursor,
      sideEnd: side.length,
    })
  }
  return changes
}

/**
 * Merge the changes from both sides into one list ordered by where they
 * start in the base, with mine's changes before theirs's at the same start.
 */
function orderChanges(mineChanges, theirsChanges) {
  const tagged = [
    ...mineChanges.map(change => ({ ...change, side: 'mine' })),
    ...theirsChanges.map(change => ({ ...change, side: 'theirs' })),
  ]
  tagged.sort((a, b) => {
    if (a.baseStart !== b.baseStart) return a.baseStart - b.baseStart
    if (a.side === b.side) return 0
    return a.side === 'mine' ? -1 : 1
  })
  return tagged
}

/**
 * Group ordered changes into regions: a region runs from the first
 * remaining change's base start to its base end, absorbing further changes
 * while they start at or before the region's current end.
 */
function groupIntoRegions(changes) {
  const regions = []
  let i = 0
  while (i < changes.length) {
    const first = changes[i]
    let regionStart = first.baseStart
    let regionEnd = first.baseEnd
    const touching = [first]
    i++
    while (i < changes.length && changes[i].baseStart <= regionEnd) {
      regionEnd = Math.max(regionEnd, changes[i].baseEnd)
      touching.push(changes[i])
      i++
    }
    regions.push({ baseStart: regionStart, baseEnd: regionEnd, touching })
  }
  return regions
}

function linesEqual(a, b) {
  if (a.length !== b.length) return false
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return false
  return true
}

/**
 * A side's replacement for a region runs from the smallest start of its own
 * changes touching the region, moved back by however far the region begins
 * before those changes do, to the largest end of its own changes, moved
 * forward by however far the region ends after them. A side untouched by
 * any change in the region contributes the base lines unchanged.
 */
function sideLines(doc, region, sideName) {
  const own = region.touching.filter(change => change.side === sideName)
  if (own.length === 0) return doc === region.baseDoc ? region.baseSlice : region.baseSlice
  let minStart = own[0].baseStart
  let ownSideStart = own[0].sideStart
  let maxEnd = own[0].baseEnd
  let ownSideEnd = own[0].sideEnd
  for (const change of own) {
    if (change.baseStart < minStart) {
      minStart = change.baseStart
      ownSideStart = change.sideStart
    }
    if (change.baseEnd > maxEnd) {
      maxEnd = change.baseEnd
      ownSideEnd = change.sideEnd
    }
  }
  const startShift = minStart - region.baseStart
  const endShift = region.baseEnd - maxEnd
  return doc.slice(ownSideStart - startShift, ownSideEnd + endShift)
}

/**
 * Resolve a region given the full mine/base/theirs documents. Returns the
 * region's base line count, its mine lines, its base lines, its theirs
 * lines, and its resolution: 'mine', 'theirs', 'both' (the two sides made
 * the same change) or 'conflict'.
 */
function resolveRegion(region, mine, base, theirs) {
  const baseSlice = base.slice(region.baseStart, region.baseEnd)
  region.baseSlice = baseSlice
  const mineSlice = sideLinesFor(mine, region, 'mine', baseSlice)
  const theirsSlice = sideLinesFor(theirs, region, 'theirs', baseSlice)
  let kind
  if (linesEqual(mineSlice, theirsSlice)) kind = 'both'
  else if (linesEqual(mineSlice, baseSlice)) kind = 'theirs'
  else if (linesEqual(theirsSlice, baseSlice)) kind = 'mine'
  else kind = 'conflict'
  return { baseSlice, mineSlice, theirsSlice, kind }
}

function sideLinesFor(doc, region, sideName, baseSlice) {
  const own = region.touching.filter(change => change.side === sideName)
  if (own.length === 0) return baseSlice
  let minStart = own[0].baseStart
  let ownSideStart = own[0].sideStart
  let maxEnd = own[0].baseEnd
  let ownSideEnd = own[0].sideEnd
  for (const change of own) {
    if (change.baseStart < minStart) {
      minStart = change.baseStart
      ownSideStart = change.sideStart
    }
    if (change.baseEnd > maxEnd) {
      maxEnd = change.baseEnd
      ownSideEnd = change.sideEnd
    }
  }
  const startShift = minStart - region.baseStart
  const endShift = region.baseEnd - maxEnd
  return doc.slice(ownSideStart - startShift, ownSideEnd + endShift)
}

/**
 * Merge mine, base and theirs into an ordered list of parts: stable base
 * stretches kept unchanged, and resolved regions (including conflicts).
 */
export function buildMergePlan(mine, base, theirs) {
  const mineChanges = diffAgainstBase(base, mine)
  const theirsChanges = diffAgainstBase(base, theirs)
  const ordered = orderChanges(mineChanges, theirsChanges)
  const regions = groupIntoRegions(ordered)

  const parts = []
  let cursor = 0
  for (const region of regions) {
    if (region.baseStart > cursor) {
      parts.push({ type: 'stable', lines: base.slice(cursor, region.baseStart) })
    }
    const resolved = resolveRegion(region, mine, base, theirs)
    parts.push({ type: 'region', ...resolved })
    cursor = region.baseEnd
  }
  if (cursor < base.length) {
    parts.push({ type: 'stable', lines: base.slice(cursor, base.length) })
  }
  return parts
}
"}

