{"file_path":"src/format.js","content":"/**
 * Shared lexical rules for the limiter file format: the character class
 * shared by names, route prefixes and event keys, the decimal-integer
 * grammar, and the error type carrying the line number a failure occurred
 * on.
 */

const TOKEN_RE = /^[A-Za-z0-9_./:-]+$/
const UNSIGNED_INT_RE = /^(0|[1-9][0-9]*)$/

/** Thrown for any parse failure; carries the 1-based line number. */
export class CliError extends Error {
  constructor(line, reason) {
    super(reason)
    this.line = line
  }
}

/** True when `token` is a valid name, route prefix or event key. */
export function isToken(token) {
  return TOKEN_RE.test(token)
}

/**
 * Parses `token` as the unsigned decimal integer named `field`, requiring
 * it to be at least `min`. Throws a `CliError` on `line` when the token
 * is not a well-formed unsigned integer or falls below `min`.
 */
export function parseField(line, field, token, min) {
  if (!UNSIGNED_INT_RE.test(token)) {
    throw new CliError(line, `${field} must be an integer of at least ${min}`)
  }
  const value = BigInt(token)
  if (value < min) {
    throw new CliError(line, `${field} must be an integer of at least ${min}`)
  }
  return value
}
"}

