{"file_path":"src/policies.js","content":"/**
 * The two policy kinds, each keeping one independent state per key. All
 * arithmetic uses BigInt so refills stay exact fractions of a token and
 * ticks are never bounded by the double-precision integer range.
 */

/**
 * A token bucket. Token counts are tracked scaled by `per` (a bucket
 * holding `capacity` tokens is stored as `capacity * per`), which turns
 * the fractional refill `refill * n / per` into the exact integer
 * addition `refill * n`, with no rounding.
 */
export class TokenBucket {
  constructor(capacity, refill, per) {
    this.refill = refill
    this.per = per
    this.capacityScaled = capacity * per
    this.states = new Map()
  }

  advance(key, tick) {
    let state = this.states.get(key)
    if (state === undefined) {
      this.states.set(key, { tokensScaled: this.capacityScaled, lastTick: tick })
      return
    }
    const delta = tick - state.lastTick
    if (delta > 0n) {
      state.tokensScaled += this.refill * delta
      if (state.tokensScaled > this.capacityScaled) state.tokensScaled = this.capacityScaled
      state.lastTick = tick
    }
  }

  allows(key) {
    return this.states.get(key).tokensScaled >= this.per
  }

  record(key) {
    this.states.get(key).tokensScaled -= this.per
  }
}

/**
 * A sliding window. Remembers the ticks of the requests it recorded for
 * a key, oldest first, and forgets ticks that have aged out of the span.
 */
export class SlidingWindow {
  constructor(limit, span) {
    this.limit = limit
    this.span = span
    this.states = new Map()
  }

  advance(key, tick) {
    let ticks = this.states.get(key)
    if (ticks === undefined) {
      ticks = []
      this.states.set(key, ticks)
    }
    const threshold = tick - this.span
    let drop = 0
    while (drop < ticks.length && ticks[drop] <= threshold) drop++
    if (drop > 0) ticks.splice(0, drop)
  }

  allows(key) {
    return BigInt(this.states.get(key).length) < this.limit
  }

  record(key) {
    this.states.get(key).push(this._lastTick)
  }
}
"}

