{"file_path":"src/router.js","content":"/**
 * A trie over route prefixes, letting each key be resolved to the
 * longest declared prefix it starts with in time proportional to the
 * key's length rather than the number of routes.
 */
export class RoutePrefixTrie {
  constructor() {
    this.root = { children: new Map(), route: null }
  }

  insert(prefix, route) {
    let node = this.root
    for (const ch of prefix) {
      let next = node.children.get(ch)
      if (next === undefined) {
        next = { children: new Map(), route: null }
        node.children.set(ch, next)
      }
      node = next
    }
    node.route = route
  }

  /** Returns the route for the longest prefix `key` starts with, or null. */
  longestMatch(key) {
    let node = this.root
    let best = null
    for (const ch of key) {
      const next = node.children.get(ch)
      if (next === undefined) break
      node = next
      if (node.route !== null) best = node.route
    }
    return best
  }
}
"}

