{"file_path":"src/parser.js","content":"/**
 * Parses a limiter file into its declared policies, its route trie and
 * its ordered list of events, validating every rule the format imposes.
 * All failures throw a `CliError` naming the offending line.
 */
import { CliError, isToken, parseField } from './format.js'
import { TokenBucket, SlidingWindow } from './policies.js'
import { RoutePrefixTrie } from './router.js'

/** Splits the raw input into lines, dropping the trailing-newline artifact. */
function toLines(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

export function parseProgram(text) {
  const policies = new Map()
  const routePrefixes = new Set()
  const trie = new RoutePrefixTrie()
  const events = []
  let seenEvent = false
  let lastTick = null

  const lines = toLines(text)
  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]

    if (directive === 'bucket' || directive === 'window' || directive === 'route') {
      if (seenEvent) {
        throw new CliError(lineNumber, 'declarations must come before the first event')
      }
    }

    if (directive === 'bucket') {
      if (tokens.length !== 5) {
        throw new CliError(lineNumber, 'expected bucket <name> <capacity> <refill> <per>')
      }
      const name = tokens[1]
      if (!isToken(name)) throw new CliError(lineNumber, `invalid policy name ${name}`)
      if (policies.has(name)) throw new CliError(lineNumber, `policy ${name} is declared twice`)
      const capacity = parseField(lineNumber, 'capacity', tokens[2], 1n)
      const refill = parseField(lineNumber, 'refill', tokens[3], 0n)
      const per = parseField(lineNumber, 'per', tokens[4], 1n)
      policies.set(name, new TokenBucket(capacity, refill, per))
    } else if (directive === 'window') {
      if (tokens.length !== 4) {
        throw new CliError(lineNumber, 'expected window <name> <limit> <span>')
      }
      const name = tokens[1]
      if (!isToken(name)) throw new CliError(lineNumber, `invalid policy name ${name}`)
      if (policies.has(name)) throw new CliError(lineNumber, `policy ${name} is declared twice`)
      const limit = parseField(lineNumber, 'limit', tokens[2], 0n)
      const span = parseField(lineNumber, 'span', tokens[3], 1n)
      policies.set(name, new SlidingWindow(limit, span))
    } else if (directive === 'route') {
      if (tokens.length < 3) {
        throw new CliError(lineNumber, 'expected route <prefix> <policy>...')
      }
      const prefix = tokens[1]
      if (!isToken(prefix)) throw new CliError(lineNumber, `invalid route prefix ${prefix}`)
      if (routePrefixes.has(prefix)) {
        throw new CliError(lineNumber, `prefix ${prefix} is routed twice`)
      }
      const policyNames = tokens.slice(2)
      for (const name of policyNames) {
        if (!policies.has(name)) throw new CliError(lineNumber, `unknown policy ${name}`)
      }
      routePrefixes.add(prefix)
      trie.insert(prefix, { prefix, policyNames })
    } else if (directive === 'event') {
      if (tokens.length !== 3) {
        throw new CliError(lineNumber, 'expected event <tick> <key>')
      }
      const tick = parseField(lineNumber, 'tick', tokens[1], 0n)
      const key = tokens[2]
      if (!isToken(key)) throw new CliError(lineNumber, `invalid key ${key}`)
      if (lastTick !== null && tick < lastTick) {
        throw new CliError(lineNumber, `tick ${tick} is before tick ${lastTick}`)
      }
      lastTick = tick
      seenEvent = true
      events.push({ tick, key })
    } else {
      throw new CliError(lineNumber, `unknown directive ${directive}`)
    }
  }

  return { policies, trie, events }
}
"}

