content.arguments:
{"file_path":"src/simulate.js","content":"/**
 * Replays a parsed program's events against its policies and routes,
 * producing either the `replay` transcript or the `summary` totals.
 */

/** Resolves each event to its verdict, in log order. */
function verdicts({ policies, trie, events }) {
  const results = []
  for (const { tick, key } of events) {
    const route = trie.longestMatch(key)
    if (route === null) {
      results.push({ tick, key, allow: true, deniedBy: null })
      continue
    }
    const policyObjs = route.policyNames.map((name) => policies.get(name))
    for (const policy of policyObjs) policy.advance(key, tick)

    let deniedBy = null
    for (let i = 0; i < policyObjs.length; i++) {
      if (!policyObjs[i].allows(key)) {
        deniedBy = route.policyNames[i]
        break
      }
    }

    if (deniedBy === null) {
      for (const policy of policyObjs) policy.record(key, tick)
    }
    results.push({ tick, key, allow: deniedBy === null, deniedBy })
  }
  return results
}

export function replay(program) {
  let out = ''
  for (const v of verdicts(program)) {
    out += v.allow ? `${v.tick} ${v.key} allow\n` : `${v.tick} ${v.key} deny ${v.deniedBy}\n`
  }
  return out
}

export function summary(program) {
  const tallies = new Map()
  let totalAllowed = 0n
  let totalDenied = 0n
  for (const v of verdicts(program)) {
    let tally = tallies.get(v.key)
    if (tally === undefined) {
      tally = { allowed: 0n, denied: 0n }
      tallies.set(v.key, tally)
    }
    if (v.allow) {
      tally.allowed++
      totalAllowed++
    } else {
      tally.denied++
      totalDenied++
    }
  }

  let out = ''
  for (const key of [...tallies.keys()].sort()) {
    const tally = tallies.get(key)
    out += `${key} allowed=${tally.allowed} denied=${tally.denied}\n`
  }
  out += `total allowed=${totalAllowed} denied=${totalDenied}\n`
  return out
}
"}

