    out += v.allow ? `${v.tick} ${v.key} allow\n` : `${v.tick} ${v.key} deny ${v.deniedBy}\n`
  }
  return out
}

export function summary(program) {
  const tallies = new Map()
  let totalAllowed = 0n
  let totalDenied = 0n
  for (const v of verdicts(program)) {
    let tally = tallies.get(v.key)
    if (tally === undefined) {
      tally = { allowed: 0n, denied: 0n }
      tallies.set(v.key, tally)
    }
    if (v.allow) {
      tally.allowed++
      totalAllowed++
    } else {
      tally.denied++
      totalDenied++
    }
  }

  let out = ''
  for (const key of [...tallies.keys()].sort()) {
    const tally = tallies.get(key)
    out += `${key} allowed=${tally.allowed} denied=${tally.denied}\n`
  }
  out += `total allowed=${totalAllowed} denied=${totalDenied}\n`
  return out
}
"}

