{"file_path":"src/parser.js","content":"/**
 * Recursive-descent parser for formula bodies, producing an AST or throwing
 * ParseError when the grammar rejects the input. Precedence, loosest to
 * tightest: comparisons, `+`/`-`, `*`/`/`, `^` (right-associative), and a
 * leading unary `+`/`-` (which binds tighter than `^`).
 *
 * A range (`A1:B3`) is only accepted where it stands alone as a whole call
 * argument; anywhere else the leftover `:` token fails to parse, making the
 * cell `#ERR!` as the specification requires.
 */
import { tokenize, LexError } from './lexer.js'

export class ParseError extends Error {}

const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])
const KEYWORDS = new Set(['TRUE', 'FALSE'])
const FUNCTION_NAMES = new Set(['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF'])

class Parser {
  constructor(tokens) {
    this.tokens = tokens
    this.pos = 0
  }

  peek() {
    return this.tokens[this.pos]
  }

  next() {
    return this.tokens[this.pos++]
  }

  expect(type) {
    const t = this.next()
    if (!t || t.type !== type) throw new ParseError(`expected ${type}`)
    return t
  }

  parseProgram() {
    const expr = this.parseComparison()
    if (this.pos !== this.tokens.length) throw new ParseError('trailing tokens')
    return expr
  }

  parseComparison() {
    let left = this.parseAdditive()
    while (this.peek() && (this.peek().type === 'OP') && COMPARISON_OPS.has(this.peek().value)) {
      const op = this.next().value
      const right = this.parseAdditive()
      left = { type: 'cmp', op, left, right }
    }
    return left
  }

  parseAdditive() {
    let left = this.parseMultiplicative()
    while (this.peek() && this.peek().type === 'OP' && (this.peek().value === '+' || this.peek().value === '-')) {
      const op = this.next().value
      const right = this.parseMultiplicative()
      left = { type: 'bin', op, left, right }
    }
    return left
  }

  parseMultiplicative() {
    let left = this.parsePower()
    while (this.peek() && this.peek().type === 'OP' && (this.peek().value === '*' || this.peek().value === '/')) {
      const op = this.next().value
      const right = this.parsePower()
      left = { type: 'bin', op, left, right }
    }
    return left
  }

  parsePower() {
    const left = this.parseUnary()
    if (this.peek() && this.peek().type === 'OP' && this.peek().value === '^') {
      this.next()
      const right = this.parsePower()
      return { type: 'bin', op: '^', left, right }
    }
    return left
  }

  parseUnary() {
    if (this.peek() && this.peek().type === 'OP' && (this.peek().value === '-' || this.peek().value === '+')) {
      const op = this.next().value
      const operand = this.parseUnary()
      return { type: 'unary', op, operand }
    }
    return this.parsePrimary()
  }

  parsePrimary() {
    const t = this.peek()
    if (!t) throw new ParseError('unexpected end of formula')
    if (t.type === 'LP') {
      this.next()
      const e = this.parseComparison()
      this.expect('RP')
      return e
    }
    if (t.type === 'NUM') {
      this.next()
      return { type: 'num', value: t.value }
    }
    if (t.type === 'WORD') {
      const upper = t.value.toUpperCase()
      if (KEYWORDS.has(upper)) {
        this.next()
        return { type: 'bool', value: upper === 'TRUE' }
      }
      const next = this.tokens[this.pos + 1]
      if (next && next.type === 'LP') {
        this.next()
        this.next()
        const args = this.parseArgList()
        this.expect('RP')
        return { type: 'call', name: upper, args }
      }
      this.next()
      return { type: 'addr', word: t.value }
    }
    throw new ParseError(`unexpected token ${t.type}`)
  }

  parseArgList() {
    const args = []
    if (this.peek() && this.peek().type === 'RP') return args
    args.push(this.parseArgument())
    while (this.peek() && this.peek().type === 'COMMA') {
      this.next()
      args.push(this.parseArgument())
    }
    return args
  }

  parseArgument() {
    const t = this.peek()
    const t1 = this.tokens[this.pos + 1]
    const t2 = this.tokens[this.pos + 2]
    if (t && t.type === 'WORD' && t1 && t1.type === 'COLON' && t2 && t2.type === 'WORD') {
      const t3 = this.tokens[this.pos + 3]
      if (t3 && (t3.type === 'COMMA' || t3.type === 'RP')) {
        this.pos += 3
        return { type: 'range', from: t.value, to: t2.value }
      }
    }
    return this.parseComparison()
  }
}

/** Parse a formula body (without the leading `=`). Throws ParseError on failure. */
export function parseFormula(body) {
  let tokens
  try {
    tokens = tokenize(body)
  } catch (e) {
    if (e instanceof LexError) throw new ParseError(e.message)
    throw e
  }
  const parser = new Parser(tokens)
  return parser.parseProgram()
}

export { FUNCTION_NAMES }
"}

