{"file_path":"src/sheet.js","content":"/**
 * Parses the sheet text format into a map of cells, keyed by canonical
 * address, each already classified as a literal value or a parsed (or
 * grammar-rejected) formula.
 */
import { parseAddressWord, addressKey, compareAddresses } from './address.js'
import { parseFormula, ParseError } from './parser.js'
import { numVal, textVal, errVal, ERROR_TOKENS } from './values.js'

export class SheetError extends Error {
  constructor(line, message) {
    super(message)
    this.line = line
  }
}

const NUMBER_LITERAL = /^-?[0-9]+(\.[0-9]+)?$/

function classifyLiteral(content) {
  if (content === '') return numVal(0)
  if (ERROR_TOKENS.includes(content)) return errVal(content)
  if (NUMBER_LITERAL.test(content)) return numVal(parseFloat(content))
  return textVal(content)
}

function splitLine(stripped) {
  let idx = 0
  while (idx < stripped.length && stripped[idx] !== ' ' && stripped[idx] !== '\t') idx += 1
  const addrRaw = stripped.slice(0, idx)
  const rest = stripped.slice(idx)
  let j = 0
  while (j < rest.length && (rest[j] === ' ' || rest[j] === '\t')) j += 1
  const content = rest.slice(j)
  return { addrRaw, content }
}

/** Parse the whole sheet text. Throws SheetError on an invalid or duplicate address. */
export function parseSheet(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const cells = new Map()
  const addrs = new Map()

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const line = lines[i]
    const stripped = line.replace(/^[ \t]+/, '')
    if (stripped === '' || stripped[0] === '#') continue

    const { addrRaw, content } = splitLine(stripped)
    const addr = parseAddressWord(addrRaw)
    if (!addr) throw new SheetError(lineNo, `invalid cell address ${addrRaw.toUpperCase()}`)
    const key = addressKey(addr)
    if (cells.has(key)) throw new SheetError(lineNo, `cell ${key} is declared twice`)

    let cell
    if (content.startsWith('=')) {
      try {
        const ast = parseFormula(content.slice(1))
        cell = { isFormula: true, ast, parseFailed: false }
      } catch (e) {
        if (e instanceof ParseError) cell = { isFormula: true, parseFailed: true }
        else throw e
      }
    } else {
      cell = { isFormula: false, literalValue: classifyLiteral(content) }
    }
    cells.set(key, cell)
    addrs.set(key, addr)
  }

  const order = [...addrs.values()].sort(compareAddresses)
  return { cells, order }
}
"}

