{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */
import { parseSheet, SheetError } from './sheet.js'
import { Evaluator, collectDeps } from './evaluator.js'
import { addressKey } from './address.js'
import { formatValue } from './values.js'

function readStdin() {
  const chunks = []
  const fd = 0
  const buf = Buffer.alloc(65536)
  const fs = require('node:fs')
  for (;;) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buf, 0, buf.length, null)
    } catch (e) {
      if (e.code === 'EAGAIN') continue
      if (e.code === 'EOF') break
      throw e
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buf.slice(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const argv = process.argv.slice(2)
  if (argv.length !== 1 || (argv[0] !== 'values' && argv[0] !== 'deps')) {
    fail('usage: cli.js values|deps')
    return
  }
  const mode = argv[0]
  const input = readStdin()

  let sheet
  try {
    sheet = parseSheet(input)
  } catch (e) {
    if (e instanceof SheetError) {
      fail(`line ${e.line}: ${e.message}`)
      return
    }
    throw e
  }

  const out = []
  if (mode === 'values') {
    const evaluator = new Evaluator(sheet.cells)
    for (const addr of sheet.order) {
      const key = addressKey(addr)
      const value = evaluator.evaluateAddress(key)
      out.push(`${key}=${formatValue(value)}`)
    }
  } else {
    for (const addr of sheet.order) {
      const key = addressKey(addr)
      const cell = sheet.cells.get(key)
      const deps = cell.isFormula && !cell.parseFailed ? collectDeps(cell.ast) : []
      const depStr = deps.map((d) => ` ${addressKey(d)}`).join('')
      out.push(`${key}:${depStr}`)
    }
  }
  process.stdout.write(out.length ? out.join('\n') + '\n' : '')
}

main()
"}

