{"file_path":"src/pack.js","content":"import { computePriority, topoOrder } from './schedule.js'

/**
 * Simulates the build graph on a fixed worker count: at every instant, each
 * free worker takes the highest-priority ready task (ties by ascending
 * name) until no worker is free or no task is ready, then time advances to
 * the next worker completion.
 */
export function pack(tasks, adjacency, workerCount) {
  const order = topoOrder(tasks, adjacency)
  const priority = computePriority(tasks, adjacency, order)

  const dependents = new Map()
  for (const name of tasks.keys()) dependents.set(name, new Set())
  for (const [name, deps] of adjacency) {
    for (const dep of deps) dependents.get(dep).add(name)
  }

  const remaining = new Map()
  for (const name of tasks.keys()) remaining.set(name, adjacency.get(name).size)

  const ready = new Set()
  for (const name of tasks.keys()) if (remaining.get(name) === 0) ready.add(name)

  const workers = Array.from({ length: workerCount }, () => ({ freeAt: 0, log: [] }))
  const pending = [] // { time, task }, not yet applied to dependents

  const applyCompletionsUpTo = (time) => {
    for (let i = pending.length - 1; i >= 0; i--) {
      if (pending[i].time > time) continue
      const { task } = pending[i]
      pending.splice(i, 1)
      for (const dependent of dependents.get(task)) {
        remaining.set(dependent, remaining.get(dependent) - 1)
        if (remaining.get(dependent) === 0) ready.add(dependent)
      }
    }
  }

  const pickBest = () => {
    let best = null
    for (const name of ready) {
      if (best === null) {
        best = name
        continue
      }
      const p = priority.get(name)
      const pb = priority.get(best)
      if (p > pb || (p === pb && name < best)) best = name
    }
    return best
  }

  let time = 0
  let scheduled = 0
  const total = tasks.size

  while (scheduled < total) {
    let progressed = true
    while (progressed) {
      progressed = false
      let widx = -1
      for (let i = 0; i < workers.length; i++) {
        if (workers[i].freeAt <= time) {
          widx = i
          break
        }
      }
      if (widx === -1 || ready.size === 0) break

      const name = pickBest()
      ready.delete(name)
      const finish = time + tasks.get(name)
      workers[widx].freeAt = finish
      workers[widx].log.push({ name, start: time, finish })
      pending.push({ time: finish, task: name })
      scheduled++
      applyCompletionsUpTo(time)
      progressed = true
    }

    if (scheduled === total) break

    let next = Infinity
    for (const w of workers) if (w.freeAt > time && w.freeAt < next) next = w.freeAt
    if (next === Infinity) break
    time = next
    applyCompletionsUpTo(time)
  }

  let makespan = 0
  for (const w of workers) if (w.freeAt > makespan) makespan = w.freeAt

  return { workers, makespan }
}
"}

