{"file_path":"src/uri.js","content":"/**
 * URI reference parsing, normalization and resolution per RFC 3986.
 *
 * A parsed reference is a plain object:
 *   scheme:    string | undefined  (undefined means absent, not just empty)
 *   hasAuthority: boolean
 *   userinfo:  string | undefined  (only meaningful when hasAuthority)
 *   host:      string | undefined  (defined whenever hasAuthority is true)
 *   port:      string | undefined  (only meaningful when hasAuthority)
 *   path:      string              (always present, possibly empty)
 *   query:     string | undefined
 *   fragment:  string | undefined
 */

const DEFAULT_PORTS = { http: 80, ws: 80, https: 443, wss: 443, ftp: 21 }

/** Raised when a `%` is not followed by two hexadecimal digits. */
export class PercentEncodingError extends Error {
  constructor(field) {
    super(`the ${field} has a truncated percent-encoding`)
    this.field = field
  }
}

/** Raised when a `resolve` record has no space separating base and reference. */
export class NoSpaceError extends Error {}

/** Raised when the base of a `resolve` record writes no scheme. */
export class NoBaseSchemeError extends Error {}

function asciiLower(str) {
  return str.replace(/[A-Z]/g, (c) => String.fromCharCode(c.charCodeAt(0) + 32))
}

/** Split a URI reference into its generic components (no validation, no normalization). */
export function parseReference(str) {
  let rest = str
  let scheme

  let schemeEnd = -1
  for (let i = 0; i < rest.length; i++) {
    const c = rest[i]
    if (c === ':') {
      schemeEnd = i
      break
    }
    if (c === '/' || c === '?' || c === '#') break
  }
  if (schemeEnd !== -1) {
    scheme = rest.slice(0, schemeEnd)
    rest = rest.slice(schemeEnd + 1)
  }

  let hasAuthority = false
  let userinfo
  let host
  let port
  if (rest.startsWith('//')) {
    hasAuthority = true
    let authEnd = rest.length
    for (let j = 2; j < rest.length; j++) {
      const c = rest[j]
      if (c === '/' || c === '?' || c === '#') {
        authEnd = j
        break
      }
    }
    let authority = rest.slice(2, authEnd)
    rest = rest.slice(authEnd)

    const at = authority.lastIndexOf('@')
    if (at !== -1) {
      userinfo = authority.slice(0, at)
      authority = authority.slice(at + 1)
    }
    const bracket = authority.lastIndexOf(']')
    const colon = authority.indexOf(':', bracket + 1)
    if (colon !== -1) {
      host = authority.slice(0, colon)
      port = authority.slice(colon + 1)
    } else {
      host = authority
    }
  }

  const qm = rest.indexOf('?')
  const hm = rest.indexOf('#')
  let path
  let query
  let fragment
  if (qm === -1 && hm === -1) {
    path = rest
  } else if (hm !== -1 && (qm === -1 || hm < qm)) {
    path = rest.slice(0, hm)
    fragment = rest.slice(hm + 1)
  } else {
    path = rest.slice(0, qm)
    if (hm === -1) {
      query = rest.slice(qm + 1)
    } else {
      query = rest.slice(qm + 1, hm)
      fragment = rest.slice(hm + 1)
    }
  }

  return { scheme, hasAuthority, userinfo, host, port, path, query, fragment }
}

/** Reassemble a parsed reference back into its textual form. */
export function serializeReference(p) {
  let s = ''
  if (p.scheme !== undefined) s += p.scheme + ':'
  if (p.hasAuthority) {
    s += '//'
    if (p.userinfo !== undefined) s += p.userinfo + '@'
    s += p.host ?? ''
    if (p.port !== undefined) s += ':' + p.port
  }
  s += p.path
  if (p.query !== undefined) s += '?' + p.query
  if (p.fragment !== undefined) s += '#' + p.fragment
  return s
}

function isUnreserved(ch) {
  return /^[A-Za-z0-9\-._~]$/.test(ch)
}

/** Uppercase %XX escapes and decode the ones that encode an unreserved character. */
function normalizePercentField(str, field) {
  let out = ''
  for (let i = 0; i < str.length; i++) {
    const c = str[i]
    if (c === '%') {
      const hex = str.slice(i + 1, i + 3)
      if (!/^[0-9a-fA-F]{2}$/.test(hex)) throw new PercentEncodingError(field)
      const upper = hex.toUpperCase()
      const ch = String.fromCharCode(parseInt(upper, 16))
      out += isUnreserved(ch) ? ch : '%' + upper
      i += 2
    } else {
      out += c
    }
  }
  return out
}

/** Remove dot segments from a path per RFC 3986 section 5.2.4. */
function removeDotSegments(path) {
  let input = path
  const output = []
  while (input.length > 0) {
    if (input.startsWith('../')) {
      input = input.slice(3)
    } else if (input.startsWith('./')) {
      input = input.slice(2)
    } else if (input.startsWith('/./')) {
      input = '/' + input.slice(3)
