      input = input.slice(m[0].length)
    }
  }
  return output.join('')
}

/**
 * Apply RFC 3986 normalization to already-parsed components, in the order the
 * specification lists: scheme case, percent-encoding, host case, default
 * ports, dot segments, then the authority-with-empty-path fixup.
 */
export function normalizeParsed(p) {
  const out = { ...p }
  if (out.scheme !== undefined) out.scheme = asciiLower(out.scheme)

  // Percent-encoding is validated and normalized in this field order because
  // that is the order in which a truncated-encoding error is reported.
  out.path = normalizePercentField(out.path, 'path')
