function mergePaths(base, ref) {
  if (base.hasAuthority && base.path === '') return '/' + ref.path
  const idx = base.path.lastIndexOf('/')
  if (idx === -1) return ref.path
  return base.path.slice(0, idx + 1) + ref.path
}

/** Resolve parsed reference `ref` against parsed base `base` per RFC 3986 section 5.2.2 (strict). */
export function resolveReference(base, ref) {
  if (ref.scheme !== undefined) {
    return {
      scheme: ref.scheme,
      hasAuthority: ref.hasAuthority,
      userinfo: ref.userinfo,
      host: ref.host,
      port: ref.port,
      path: removeDotSegments(ref.path),
      query: ref.query,
      fragment: ref.fragment,
    }
  }
  if (ref.hasAuthority) {
    return {
      scheme: base.scheme,
      hasAuthority: true,
      userinfo: ref.userinfo,
      host: ref.host,
      port: ref.port,
      path: removeDotSegments(ref.path),
      query: ref.query,
      fragment: ref.fragment,
    }
  }
  if (ref.path === '') {
    return {
      scheme: base.scheme,
      hasAuthority: base.hasAuthority,
      userinfo: base.userinfo,
      host: base.host,
      port: base.port,
      path: base.path,
      query: ref.query !== undefined ? ref.query : base.query,
      fragment: ref.fragment,
    }
  }
  const mergedPath = ref.path.startsWith('/') ? ref.path : mergePaths(base, ref)
  return {
    scheme: base.scheme,
    hasAuthority: base.hasAuthority,
    userinfo: base.userinfo,
    host: base.host,
    port: base.port,
    path: removeDotSegments(mergedPath),
    query: ref.query,
    fragment: ref.fragment,
  }
}

/** Resolve reference text against base text, then normalize the result. */
export function resolve(baseStr, refStr) {
  const base = parseReference(baseStr)
  if (base.scheme === undefined) throw new NoBaseSchemeError()
  const ref = parseReference(refStr)
  return serializeReference(normalizeParsed(resolveReference(base, ref)))
}
