/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */

import { readFileSync } from 'node:fs'
import { normalize, resolve, NoSpaceError, NoBaseSchemeError, PercentEncodingError } from './uri.js'

const mode = process.argv[2]
if (process.argv.length !== 3 || (mode !== 'normalize' && mode !== 'resolve')) {
  process.stderr.write('error: usage: cli.js normalize|resolve\n')
  process.exit(2)
}

const input = readFileSync(0, 'utf8')
const lines = input.split('\n')
if (lines[lines.length - 1] === '') lines.pop()

const outputs = []
for (let i = 0; i < lines.length; i++) {
  const lineNo = i + 1
  const record = lines[i]
  try {
    if (mode === 'normalize') {
      outputs.push(normalize(record))
    } else {
      const spaceIdx = record.indexOf(' ')
      if (spaceIdx === -1) throw new NoSpaceError()
      const baseStr = record.slice(0, spaceIdx)
      const refStr = record.slice(spaceIdx + 1)
      outputs.push(resolve(baseStr, refStr))
    }
  } catch (e) {
    let message
    if (e instanceof NoSpaceError) message = 'expected a base and a reference'
    else if (e instanceof NoBaseSchemeError) message = 'the base has no scheme'
    else if (e instanceof PercentEncodingError) message = e.message
    else throw e
    process.stderr.write(`error: line ${lineNo}: ${message}\n`)
    process.exit(2)
  }
}

process.stdout.write(outputs.map((line) => line + '\n').join(''))
"}

