{"file_path":"src/position.js","content":"/** Column arithmetic shared by the INI grammar and the environment layer. */

/** The 1-based column of the first non-space character of `raw`. */
export function indent(raw) {
  return raw.length - raw.trimStart().length + 1
}

/**
 * The 1-based column of a `name = value` (or `NAME=VALUE`) line's value: its first
 * character, or, when the value is empty, one past the line's last non-space character.
 * @param {string} raw - the untrimmed line.
 * @param {string} trimmed - `raw.trim()`.
 * @param {number} split - the index of the separator (`=`) within `trimmed`.
 */
export function valueColumn(raw, trimmed, split) {
  const after = trimmed.slice(split + 1)
  if (after.trim() === '') return indent(raw) + trimmed.length
  const lead = after.length - after.trimStart().length
  return indent(raw) + split + 1 + lead
}
"}

