{"file_path":"src/env.js","content":"/** The environment layer: `CONF_`-prefixed variables read one per line from standard input. */

import { PositionError } from './errors.js'
import { indent, valueColumn } from './position.js'
import { SETTINGS, envName } from './schema.js'

/** One refusal of an environment line, carrying the 1-based line and column it was read at. */
export class EnvError extends PositionError {
  constructor(line, column, message) {
    super(line, column, message)
    this.name = 'EnvError'
  }
}

const KEY_FOR_NAME = new Map(SETTINGS.map(declared => [envName(declared.key), declared.key]))

/**
 * Parse environment text into its settings.
 * @param {string} text - the whole standard input.
 * @returns {Map<string, {text: string, line: number, column: number}>} each schema key's raw
 *   value and the position it was written at, keyed by the schema key the `CONF_` name names.
 * @throws {EnvError} on the first line the grammar refuses.
 */
export function parseEnv(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  const values = new Map()
  for (const [index, raw] of lines.entries()) {
    const line = index + 1
    const trimmed = raw.trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue
    const column = indent(raw)
    const split = trimmed.indexOf('=')
    if (split === -1) throw new EnvError(line, column, 'expected NAME=VALUE')
    const name = trimmed.slice(0, split).trim()
    if (name === '') throw new EnvError(line, column, 'expected a variable name')
    const key = KEY_FOR_NAME.get(name)
    if (key === undefined) throw new EnvError(line, column, `unknown environment variable ${name}`)
    if (values.has(key)) throw new EnvError(line, column, `${name} is set twice`)
    values.set(key, { text: trimmed.slice(split + 1).trim(), line, column: valueColumn(raw, trimmed, split) })
  }
  return values
}
"}

