 * Parsing, normalization and resolution of URI references, following
 * RFC 3986's generic syntax (section 3), percent-encoding normalization
 * (section 6.2.2), dot-segment removal (section 5.2.4) and strict
 * reference resolution (section 5.2.2).
 */

/** Thrown when a component holds a `%` that is not followed by two hex digits. */
export class TruncatedPercentEncodingError extends Error {
  constructor(component) {
    super(`the ${component} has a truncated percent-encoding`)
    this.component = component
  }
}

const DEFAULT_PORTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

/**
 * Parse a URI reference into its five generic components. Each of
 * scheme, authority, query and fragment is either `null`, meaning
 * absent, or a string, meaning present (possibly empty). `path` is
 * always a string.
 */
export function parse(ref) {
  let rest = ref
  let scheme = null

  const delim = /[:/?#]/.exec(rest)
  if (delim && delim[0] === ':') {
    scheme = rest.slice(0, delim.index)
    rest = rest.slice(delim.index + 1)
  }

  let authority = null
  if (rest.startsWith('//')) {
    const end = /[/?#]/.exec(rest.slice(2))
    const endIndex = end ? end.index + 2 : rest.length
    authority = rest.slice(2, endIndex)
    rest = rest.slice(endIndex)
  }

  const pathEnd = /[?#]/.exec(rest)
  const pathEndIndex = pathEnd ? pathEnd.index : rest.length
  const path = rest.slice(0, pathEndIndex)
  rest = rest.slice(pathEndIndex)

  let query = null
  if (rest.startsWith('?')) {
    const fragStart = rest.indexOf('#')
    if (fragStart === -1) {
      query = rest.slice(1)
      rest = ''
    } else {
      query = rest.slice(1, fragStart)
      rest = rest.slice(fragStart)
    }
  }

  let fragment = null
  if (rest.startsWith('#')) {
    fragment = rest.slice(1)
  }

  return { scheme, authority, path, query, fragment }
}

/** Split an authority string into its userinfo, host and port parts. */
export function splitAuthority(authority) {
  let userinfo = null
  let rest = authority
  const at = rest.lastIndexOf('@')
  if (at !== -1) {
    userinfo = rest.slice(0, at)
    rest = rest.slice(at + 1)
  }

  const bracket = rest.lastIndexOf(']')
  const searchFrom = bracket === -1 ? 0 : bracket + 1
  const colon = rest.indexOf(':', searchFrom)

  let host
  let port = null
  if (colon === -1) {
    host = rest
  } else {
    host = rest.slice(0, colon)
    port = rest.slice(colon + 1)
  }

  return { userinfo, host, port }
}

function combineAuthority(userinfo, host, port) {
  return (userinfo === null ? '' : `${userinfo}@`) + host + (port === null ? '' : `:${port}`)
}

/** Serialize a parsed URI reference back into a string. */
export function serialize({ scheme, authority, path, query, fragment }) {
  let out = ''
  if (scheme !== null) out += `${scheme}:`
  if (authority !== null) out += `//${authority}`
  out += path
  if (query !== null) out += `?${query}`
  if (fragment !== null) out += `#${fragment}`
  return out
}

function isUnreservedByte(code) {
  return (
    (code >= 0x41 && code <= 0x5a) || // A-Z
    (code >= 0x61 && code <= 0x7a) || // a-z
    (code >= 0x30 && code <= 0x39) || // 0-9
    code === 0x2d || // -
    code === 0x2e || // .
    code === 0x5f || // _
    code === 0x7e // ~
  )
}

function isHexDigit(ch) {
  return /[0-9A-Fa-f]/.test(ch)
}

/**
 * Uppercase the hex digits of every `%XX` triplet in `text`, then decode
 * the triplets that encode an unreserved character. Throws
 * `TruncatedPercentEncodingError` naming `component` when a `%` is not
 * followed by two hex digits.
 */
export function normalizePercentEncoding(text, component) {
  let out = ''
  for (let i = 0; i < text.length; i++) {
    const ch = text[i]
    if (ch !== '%') {
      out += ch
      continue
    }
    const hex = text.slice(i + 1, i + 3)
    if (hex.length !== 2 || !isHexDigit(hex[0]) || !isHexDigit(hex[1])) {
      throw new TruncatedPercentEncodingError(component)
    }
    const upperHex = hex.toUpperCase()
    const code = parseInt(upperHex, 16)
    if (isUnreservedByte(code)) {
      out += String.fromCharCode(code)
    } else {
      out += `%${upperHex}`
    }
    i += 2
  }
  return out
}

function asciiLowercase(text) {
  return text.replace(/[A-Z]/g, (c) => c.toLowerCase())
}

/** Remove `.` and `..` segments from a path, per RFC 3986 section 5.2.4. */
export function removeDotSegments(path) {
  let input = path
  let output = ''

  while (input.length > 0) {
    if (input.startsWith('../')) {
      input = input.slice(3)
    } else if (input.startsWith('./')) {
      input = input.slice(2)
    } else if (input.startsWith('/./')) {
      input = `/${input.slice(3)}`
    } else if (input === '/.') {
      input = '/'
    } else if (input.startsWith('/../')) {
      input = `/${input.slice(4)}`
      output = output.slice(0, output.lastIndexOf('/'))
    } else if (input === '/..') {
      input = '/'
      output = output.slice(0, output.lastIndexOf('/'))
    } else if (input === '.' || input === '..') {
      input = ''
    } else {
      const startsWithSlash = input[0] === '/'
      const searchFrom = startsWithSlash ? 1 : 0
      const nextSlash = input.indexOf('/', searchFrom)
      const segment = nextSlash === -1 ? input : input.slice(0, nextSlash)
      input = nextSlash === -1 ? '' : input.slice(nextSlash)
      output += segment
    }
  }

  return output
}

/**
 * Normalize a parsed URI reference: lowercase the scheme, normalize
 * percent-encodings in userinfo, host, path, query and fragment (in
 * that order, so a truncated encoding is reported for the first of
 * those that carries one), lowercase the host, drop a default port,
 * remove dot segments from the path, and root the path when an
 * authority is present and the path is empty.
 */
export function normalize(ref) {
  const scheme = ref.scheme === null ? null : asciiLowercase(ref.scheme)

  let authority = null
  if (ref.authority !== null) {
    const { userinfo, host, port } = splitAuthority(ref.authority)
    const normalizedUserinfo = userinfo === null ? null : normalizePercentEncoding(userinfo, 'userinfo')
    let normalizedHost = normalizePercentEncoding(host, 'host')
    normalizedHost = asciiLowercase(normalizedHost)
    let normalizedPort = port
    if (normalizedPort !== null) {
      const defaultPort = scheme === null ? undefined : DEFAULT_PORTS[scheme]
      if (normalizedPort === '' || normalizedPort === defaultPort) {
        normalizedPort = null
      }
    }
    authority = combineAuthority(normalizedUserinfo, normalizedHost, normalizedPort)
  }

  let path = normalizePercentEncoding(ref.path, 'path')
  const query = ref.query === null ? null : normalizePercentEncoding(ref.query, 'query')
  const fragment = ref.fragment === null ? null : normalizePercentEncoding(ref.fragment, 'fragment')

  path = removeDotSegments(path)
  if (authority !== null && path === '') {
    path = '/'
  }

  return { scheme, authority, path, query, fragment }
}

function merge(base, refPath) {
  if (base.authority !== null && base.path === '') {
    return `/${refPath}`
  }
  const lastSlash = base.path.lastIndexOf('/')
  if (lastSlash === -1) {
    return refPath
  }
  return base.path.slice(0, lastSlash + 1) + refPath
}

/**
 * Resolve `ref` against `base` following RFC 3986 section 5.2.2 in its
 * strict form. `base` must already have a scheme. The result is not
 * normalized; callers should pass it through `normalize`.
 */
export function resolve(base, ref) {
  let scheme
  let authority
  let path
  let query

  if (ref.scheme !== null) {
    scheme = ref.scheme
    authority = ref.authority
    path = ref.path
    query = ref.query
  } else if (ref.authority !== null) {
    scheme = base.scheme
    authority = ref.authority
    path = ref.path
    query = ref.query
  } else if (ref.path === '') {
    scheme = base.scheme
    authority = base.authority
    path = base.path
    query = ref.query !== null ? ref.query : base.query
  } else {
    scheme = base.scheme
    authority = base.authority
    if (ref.path.startsWith('/')) {
      path = ref.path
    } else {
      path = merge(base, ref.path)
    }
    query = ref.query
  }

  return { scheme, authority, path, query, fragment: ref.fragment }
}
