/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */

import { readFileSync } from 'node:fs'
import { parse, serialize, normalize, resolve, TruncatedPercentEncodingError } from './uri.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function splitRecords(input) {
  if (input === '') return []
  const parts = input.split('\n')
  if (parts[parts.length - 1] === '') parts.pop()
  return parts
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'normalize' && args[0] !== 'resolve')) {
    fail('usage: cli.js normalize|resolve')
  }
  const mode = args[0]

  const input = readFileSync(0, 'utf8')
  const records = splitRecords(input)
  const results = []

  for (let i = 0; i < records.length; i++) {
    const lineNumber = i + 1
    const record = records[i]
    try {
      if (mode === 'normalize') {
        results.push(serialize(normalize(parse(record))))
      } else {
        const spaceIndex = record.indexOf(' ')
        if (spaceIndex === -1) {
          throw new Error('expected a base and a reference')
