{"file_path":"src/format.js","content":"/**
 * Renders a completed count into the text the two CLI modes print.
 */

/** Formats one round as `round K: name=votes ... exhausted=n`. */
function formatRound(index, round) {
  const entries = [...round.counts.entries()].sort(([nameA, votesA], [nameB, votesB]) => {
    if (votesA !== votesB) return votesA > votesB ? -1 : 1
    return nameA < nameB ? -1 : nameA > nameB ? 1 : 0
  })
  const parts = entries.map(([name, votes]) => `${name}=${votes}`)
  parts.push(`exhausted=${round.exhausted}`)
  return `round ${index + 1}: ${parts.join(' ')}`
}

/** Formats the trailing outcome line shared by both modes. */
function formatWinner(winner) {
  return winner === null ? 'no winner' : `winner ${winner}`
}

/** Renders the full `rounds` output. */
export function formatRounds(result) {
  const lines = []
  result.rounds.forEach((round, index) => {
    lines.push(formatRound(index, round))
    if (round.eliminated !== null) lines.push(`eliminated ${round.eliminated}`)
  })
  lines.push(formatWinner(result.winner))
  return lines.join('\n') + '\n'
}

/** Renders the full `tally` output. */
export function formatTally(result) {
  return `rounds ${result.rounds.length}\n${formatWinner(result.winner)}\n`
}
"}

