{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/** The command: `order`, `show <name>`, `files <name>`, `digest <path>...` and `plan <snapshot>`. */

import { existsSync, readFileSync } from 'node:fs'
import { digestBytes } from './digest.js'
import { CycleError, order } from './graph.js'
import { parse, ParseError, splitLines } from './parse.js'
import { parseSnapshot, SnapshotError } from './snapshot.js'

const USAGE = 'usage: cli.js order|show <name>|files <name>|digest <path>...|plan <snapshot>'

/** Report one failure the way the specification words it, and stop. */
function fail(message, code = 2) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(code)
}

/** One `show` or `files` field, with `-` standing for an empty list. */
function field(label, values) {
  return `${label}: ${values.length === 0 ? '-' : [...values].sort().join(' ')}`
}

/** The digest of a workspace path, or `missing` when it is not there. */
function digestPath(path) {
  return existsSync(path) ? digestBytes(readFileSync(path)) : undefined
}

const argv = process.argv.slice(2)
const mode = argv[0]
const arity = { order: 1, show: 2, files: 2, plan: 2 }
if (mode === 'digest' ? argv.length < 2 : argv.length !== arity[mode]) fail(USAGE)

let tasks
try {
  tasks = parse(splitLines(readFileSync(0, 'utf8')))
} catch (error) {
  if (!(error instanceof ParseError)) throw error
  fail(error.line === 0 ? error.message : `line ${error.line}: ${error.message}`)
}

/** The run order, or a clean exit-3 report of the first cycle found. */
function runOrder() {
  try {
    return order(tasks)
  } catch (error) {
    if (!(error instanceof CycleError)) throw error
    fail(error.message, 3)
    return undefined
  }
}

const out = []
if (mode === 'order') {
  out.push(...runOrder())
} else if (mode === 'show') {
  const task = tasks.get(argv[1])
  if (task === undefined) fail(`unknown task ${argv[1]}`)
  out.push(`${task.name}: ${task.command}`)
  out.push(field('needs', task.needs))
} else if (mode === 'files') {
  const task = tasks.get(argv[1])
  if (task === undefined) fail(`unknown task ${argv[1]}`)
  out.push(field('reads', task.reads))
  out.push(field('writes', task.writes))
} else if (mode === 'digest') {
  for (const path of argv.slice(1)) {
    out.push(`${path} ${digestPath(path) ?? 'missing'}`)
  }
} else {
  let snapshot
  try {
    snapshot = parseSnapshot(argv[1])
  } catch (error) {
    if (!(error instanceof SnapshotError)) throw error
    fail(error.message)
  }
  const sequence = runOrder()
  const ran = new Set()
  let runCount = 0
  let skipCount = 0
  for (const name of sequence) {
    const task = tasks.get(name)
    const watched = [...new Set([...task.reads, ...task.writes])].sort()
    let reason
    for (const path of watched) {
      const recorded = snapshot.get(path)
      if (recorded === undefined) {
        reason = `new ${path}`
      } else {
        const actual = digestPath(path)
        reason = actual === undefined ? `missing ${path}` : actual === recorded ? undefined : `changed ${path}`
      }
      if (reason !== undefined) break
    }
    if (reason === undefined) {
      for (const dependency of [...task.needs].sort()) {
        if (ran.has(dependency)) {
          reason = `needs ${dependency}`
          break
        }
      }
    }
    if (reason === undefined) {
      skipCount += 1
      out.push(`skip ${name}`)
    } else {
      ran.add(name)
      runCount += 1
      out.push(`run ${name} ${reason}`)
    }
  }
  out.push(`total run=${runCount} skip=${skipCount}`)
}
process.stdout.write(out.map(line => `${line}\n`).join(''))
"}

