 * URI reference parsing, normalization and resolution per RFC 3986.
 */

const UNRESERVED = /[A-Za-z0-9\-._~]/
const DEFAULT_PORTS = { http: '80', https: '443', ws: '80', wss: '443', ftp: '21' }

/** Thrown when a component holds a `%` not followed by two hex digits. */
export class TruncatedPercentEncodingError extends Error {
  constructor(component) {
    super(`the ${component} has a truncated percent-encoding`)
    this.component = component
  }
}

/** Thrown when a `resolve` record's base writes no scheme. */
export class BaseSchemeError extends Error {
  constructor() {
    super('the base has no scheme')
  }
}

function asciiLower(s) {
  return s.replace(/[A-Z]/g, (c) => c.toLowerCase())
}

/**
 * Splits a URI reference into its generic components. An absent component is
 * `undefined`; a present-but-empty one is `''`. No percent-decoding happens
 * here: that is deferred to normalization so resolution can operate on the
 * literal, unnormalized syntax first, as RFC 3986 5.2.2 requires.
 */
export function parseReference(str) {
  let rest = str
  let fragment
  const hashIdx = rest.indexOf('#')
  if (hashIdx !== -1) {
    fragment = rest.slice(hashIdx + 1)
    rest = rest.slice(0, hashIdx)
  }

  let query
  const qIdx = rest.indexOf('?')
  if (qIdx !== -1) {
    query = rest.slice(qIdx + 1)
    rest = rest.slice(0, qIdx)
  }

  let scheme
  const colonIdx = rest.indexOf(':')
  if (colonIdx !== -1 && !rest.slice(0, colonIdx).includes('/')) {
    scheme = rest.slice(0, colonIdx)
    rest = rest.slice(colonIdx + 1)
  }

  let authority
  if (rest.startsWith('//')) {
    const slashIdx = rest.indexOf('/', 2)
    const end = slashIdx === -1 ? rest.length : slashIdx
    authority = rest.slice(2, end)
    rest = rest.slice(end)
  }

  return { scheme, authority, path: rest, query, fragment }
}

/**
 * Splits an authority into userinfo, host and port. Userinfo is everything
 * before the last `@`; the port is everything after the first `:` following
 * the last `]`; the host is what remains between them.
 */
function parseAuthority(authority) {
  if (authority === undefined) return { userinfo: undefined, host: undefined, port: undefined }

  let rest = authority
  let userinfo
  const atIdx = rest.lastIndexOf('@')
  if (atIdx !== -1) {
    userinfo = rest.slice(0, atIdx)
    rest = rest.slice(atIdx + 1)
  }

  const bracketIdx = rest.lastIndexOf(']')
  const colonIdx = rest.indexOf(':', bracketIdx + 1)
  let host = rest
  let port
  if (colonIdx !== -1) {
    host = rest.slice(0, colonIdx)
    port = rest.slice(colonIdx + 1)
  }

  return { userinfo, host, port }
}

/**
 * Uppercases the hex digits of every `%XX` in `str` and replaces the triplet
 * with the character it encodes when that character is unreserved. Throws
 * `TruncatedPercentEncodingError` for `component` if a `%` lacks two
 * following hex digits.
 */
function normalizePercentEncoding(str, component) {
  let result = ''
  for (let i = 0; i < str.length; i++) {
    if (str[i] === '%') {
      const hex = str.slice(i + 1, i + 3)
      if (!/^[0-9A-Fa-f]{2}$/.test(hex)) throw new TruncatedPercentEncodingError(component)
      const upper = hex.toUpperCase()
      const ch = String.fromCharCode(parseInt(upper, 16))
      result += UNRESERVED.test(ch) ? ch : `%${upper}`
      i += 2
    } else {
      result += str[i]
    }
  }
  return result
}

/** Removes `.` and `..` segments from a path per RFC 3986 5.2.4. */
function removeDotSegments(path) {
  let input = path
  let output = ''
  while (input.length > 0) {
    if (input.startsWith('../')) {
      input = input.slice(3)
    } else if (input.startsWith('./')) {
      input = input.slice(2)
    } else if (input.startsWith('/./')) {
      input = `/${input.slice(3)}`
    } else if (input === '/.') {
      input = '/'
    } else if (input.startsWith('/../')) {
      input = `/${input.slice(4)}`
      output = output.slice(0, Math.max(0, output.lastIndexOf('/')))
    } else if (input === '/..') {
      input = '/'
      output = output.slice(0, Math.max(0, output.lastIndexOf('/')))
    } else if (input === '.' || input === '..') {
      input = ''
    } else {
      const searchFrom = input[0] === '/' ? 1 : 0
      const idx = input.indexOf('/', searchFrom)
      const segment = idx === -1 ? input : input.slice(0, idx)
      input = idx === -1 ? '' : input.slice(idx)
      output += segment
    }
  }
  return output
}

/**
 * Normalizes a parsed component set: lowercases the scheme and host,
 * percent-decodes unreserved characters (checking for truncation in the
 * order path, userinfo, host, query, fragment), drops a default or empty
 * port, removes dot segments from the path, and forces an authority's empty
 * path to `/`.
 */
export function normalizeComponents(components) {
  const scheme = components.scheme !== undefined ? asciiLower(components.scheme) : undefined
  const { userinfo: rawUserinfo, host: rawHost, port: rawPort } = parseAuthority(components.authority)

  const path = normalizePercentEncoding(components.path, 'path')
  const userinfo = rawUserinfo !== undefined ? normalizePercentEncoding(rawUserinfo, 'userinfo') : undefined
  const host = rawHost !== undefined ? normalizePercentEncoding(rawHost, 'host') : undefined
  const query = components.query !== undefined ? normalizePercentEncoding(components.query, 'query') : undefined
  const fragment = components.fragment !== undefined ? normalizePercentEncoding(components.fragment, 'fragment') : undefined

  const lowerHost = host !== undefined ? asciiLower(host) : undefined

  let port = rawPort
  if (port !== undefined) {
    const defaultPort = scheme !== undefined ? DEFAULT_PORTS[scheme] : undefined
    if (port === '' || port === defaultPort) port = undefined
  }

  let authority = components.authority
  if (authority !== undefined) {
    authority = `${userinfo !== undefined ? `${userinfo}@` : ''}${lowerHost ?? ''}${port !== undefined ? `:${port}` : ''}`
  }

  let normalizedPath = removeDotSegments(path)
  if (authority !== undefined && normalizedPath === '') normalizedPath = '/'

  return { scheme, authority, path: normalizedPath, query, fragment }
}

/** Serializes normalized components back into a URI reference string. */
export function serialize(components) {
  let out = ''
  if (components.scheme !== undefined) out += `${components.scheme}:`
  if (components.authority !== undefined) out += `//${components.authority}`
  out += components.path
  if (components.query !== undefined) out += `?${components.query}`
  if (components.fragment !== undefined) out += `#${components.fragment}`
  return out
}

/** Normalizes a URI reference string. */
export function normalize(str) {
  return serialize(normalizeComponents(parseReference(str)))
}

/** Merges a relative-path reference onto a base path per RFC 3986 5.2.3. */
function merge(basePath, refPath, baseHasAuthority) {
  if (baseHasAuthority && basePath === '') return `/${refPath}`
  const idx = basePath.lastIndexOf('/')
  return idx === -1 ? refPath : basePath.slice(0, idx + 1) + refPath
}

/**
 * Resolves `refStr` against `baseStr` per RFC 3986 5.2.2 (strict form), then
 * normalizes the result. Throws `BaseSchemeError` if the base writes no
 * scheme.
 */
export function resolve(baseStr, refStr) {
  const base = parseReference(baseStr)
  if (base.scheme === undefined) throw new BaseSchemeError()
  const ref = parseReference(refStr)

  let target
  if (ref.scheme !== undefined) {
    target = { scheme: ref.scheme, authority: ref.authority, path: removeDotSegments(ref.path), query: ref.query, fragment: ref.fragment }
  } else if (ref.authority !== undefined) {
    target = { scheme: base.scheme, authority: ref.authority, path: removeDotSegments(ref.path), query: ref.query, fragment: ref.fragment }
  } else if (ref.path === '') {
    target = {
      scheme: base.scheme,
      authority: base.authority,
      path: base.path,
      query: ref.query !== undefined ? ref.query : base.query,
      fragment: ref.fragment,
    }
  } else {
    const path = ref.path.startsWith('/')
      ? removeDotSegments(ref.path)
      : removeDotSegments(merge(base.path, ref.path, base.authority !== undefined))
    target = { scheme: base.scheme, authority: base.authority, path, query: ref.query, fragment: ref.fragment }
  }

  return serialize(normalizeComponents(target))
}
"}

