      : removeDotSegments(merge(base.path, ref.path, base.authority !== undefined))
    target = { scheme: base.scheme, authority: base.authority, path, query: ref.query, fragment: ref.fragment }
  }

  return serialize(normalizeComponents(target))
}
"}

