/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 *
 * Output is buffered until every record has been processed: a failure on
 * any line must leave standard output untouched.
 */

import { normalize, resolve } from './uri.js'

function readStdin() {
  const chunks = []
  const fd = 0
  const buffer = Buffer.alloc(65536)
  const fs = require('node:fs')
  for (;;) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buffer, 0, buffer.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buffer.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function splitRecords(text) {
  if (text === '') return []
  const parts = text.split('\n')
  if (parts[parts.length - 1] === '') parts.pop()
  return parts
}

function fail(lineNumber, message) {
  process.stderr.write(`error: line ${lineNumber}: ${message}\n`)
  process.exit(2)
}

function main() {
  const args = process.argv.slice(2)
  const mode = args[0]
  if (args.length !== 1 || (mode !== 'normalize' && mode !== 'resolve')) {
    process.stderr.write('error: usage: cli.js normalize|resolve\n')
    process.exit(2)
  }

  const records = splitRecords(readStdin())
  const results = []

  for (let i = 0; i < records.length; i++) {
    const lineNumber = i + 1
    const record = records[i]
    try {
      if (mode === 'normalize') {
        results.push(normalize(record))
      } else {
        const spaceIdx = record.indexOf(' ')
        if (spaceIdx === -1) fail(lineNumber, 'expected a base and a reference')
        const base = record.slice(0, spaceIdx)
        const reference = record.slice(spaceIdx + 1)
        results.push(resolve(base, reference))
      }
    } catch (err) {
      fail(lineNumber, err.message)
    }
  }

  process.stdout.write(results.map((line) => `${line}\n`).join(''))
}

main()
"}

