/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */

import { computeBlocks } from './merge.js'

const MODES = ['merge', 'merge2', 'regions']

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function splitLines(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

function splitDocuments(lines) {
  const docs = [[]]
  for (const line of lines) {
    if (line === '%%%') docs.push([])
    else docs[docs.length - 1].push(line)
  }
  return docs
}

function renderMerge(blocks, withBase) {
  const out = []
  let conflicted = false
  for (const block of blocks) {
    if (block.kind === 'conflict') {
      conflicted = true
      out.push('<<<<<<< mine', ...block.mine)
      if (withBase) out.push('||||||| base', ...block.base)
      out.push('=======', ...block.theirs, '>>>>>>> theirs')
    } else {
      out.push(...block.lines)
    }
  }
  return { text: out.length === 0 ? '' : out.join('\n') + '\n', conflicted }
}

function renderRegions(blocks) {
  const out = []
  let conflicted = false
  for (const block of blocks) {
    if (block.kind === 'conflict') {
      conflicted = true
      out.push(`conflict mine=${block.mine.length} base=${block.base.length} theirs=${block.theirs.length}`)
    } else {
      out.push(`${block.kind} ${block.lines.length}`)
    }
  }
  return { text: out.length === 0 ? '' : out.join('\n') + '\n', conflicted }
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || !MODES.includes(mode)) fail('usage: cli.js merge|merge2|regions')

  const input = require('node:fs').readFileSync(0, 'utf8')
  const docs = splitDocuments(splitLines(input))
  if (docs.length !== 3) fail('expected three parts separated by %%%')

  const [mine, base, theirs] = docs
  const blocks = computeBlocks(mine, base, theirs)
  const { text, conflicted } = mode === 'regions' ? renderRegions(blocks) : renderMerge(blocks, mode === 'merge')

  process.stdout.write(text)
  process.exit(conflicted ? 1 : 0)
}

main()
"}

