  assert.deepEqual(run(['order'], ''), { code: 0, out: '', err: '' })
})

test('comments and blank lines are ignored', () => {
  assert.equal(run(['order'], '# build\n\ntask a echo a\n').out, 'a\n')
})

test('show prints the command and the dependencies', () => {
