/** A dependency cycle found while ordering the graph, carrying the names around it. */
export class CycleError extends Error {
  /**
   * @param {string[]} cycle - the names from the re-entered task, through the search stack, back to it.
   */
  constructor(cycle) {
    super(`cycle: ${cycle.join(' -> ')}`)
    this.name = 'CycleError'
    this.cycle = cycle
  }
}

/**
 * The first cycle a depth-first search finds, starting from each task in ascending name order and
 * walking each task's dependencies in ascending name order.
 * @param {Map<string, {needs: string[]}>} tasks - the parsed tasks.
 * @returns {string[]|null} the cycle's names, from the re-entered task back to it, or null when there is none.
 */
function findCycle(tasks) {
  const visited = new Set()
  const stack = []
  const onStack = new Set()

  function visit(name) {
    stack.push(name)
    onStack.add(name)
    for (const dep of [...tasks.get(name).needs].sort()) {
      if (onStack.has(dep)) return [...stack.slice(stack.indexOf(dep)), dep]
      if (!visited.has(dep)) {
        const found = visit(dep)
        if (found) return found
      }
    }
    stack.pop()
    onStack.delete(name)
    visited.add(name)
    return null
  }

  for (const name of [...tasks.keys()].sort()) {
    if (!visited.has(name)) {
      const found = visit(name)
      if (found) return found
    }
  }
  return null
}

/**
 * The tasks in run order: repeatedly the lexicographically smallest task whose
 * dependencies have all been emitted.
 * @param {Map<string, {needs: string[]}>} tasks - the parsed tasks.
 * @returns {string[]} the names in run order.
 * @throws {CycleError} when the graph has a dependency cycle.
 */
export function order(tasks) {
  const cycle = findCycle(tasks)
  if (cycle) throw new CycleError(cycle)

  const remaining = new Set(tasks.keys())
  const emitted = new Set()
  const out = []
  while (remaining.size > 0) {
    const ready = [...remaining].filter(name => tasks.get(name).needs.every(need => emitted.has(need))).sort()
    if (ready.length === 0) break
    remaining.delete(ready[0])
    emitted.add(ready[0])
    out.push(ready[0])
  }
  return out
}
"}

