{"file_path":"src/parser.js","content":"/**
 * Recursive-descent parser for formula bodies, built on the token stream
 * from lexer.js.
 *
 * Precedence, loosest first: comparisons, then + and -, then * and /, then
 * ^, then a leading unary - or +. The comparisons and the additive and
 * multiplicative operators group to the left; ^ groups to the right and
 * binds looser than a leading unary sign, so -2^2 is 4 and 2^3^2 is 512.
 *
 * A range (address:address) is grammar-valid wherever an address is, but
 * is only meaningful directly as a function argument; using it anywhere
 * else is a semantic error handled by the evaluator, not a parse failure.
 */
import { tokenize } from './lexer.js'

const COMPARISON_TYPES = new Set(['EQ', 'NE', 'LE', 'LT', 'GE', 'GT'])
const FUNCTION_NAMES = new Set(['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF'])

class ParseError extends Error {}

class Parser {
  constructor(tokens) {
    this.tokens = tokens
    this.pos = 0
  }

  peek() {
    return this.tokens[this.pos]
  }

  at(type) {
    return this.peek().type === type
  }

  next() {
    return this.tokens[this.pos++]
  }

  expect(type) {
    if (!this.at(type)) throw new ParseError()
    return this.next()
  }

  parseProgram() {
    const e = this.parseComparison()
    this.expect('EOF')
    return e
  }

  parseComparison() {
    let left = this.parseAdditive()
    while (COMPARISON_TYPES.has(this.peek().type)) {
      const op = this.next().type
      const right = this.parseAdditive()
      left = { type: 'binop', op, left, right }
    }
    return left
  }

  parseAdditive() {
    let left = this.parseMultiplicative()
    while (this.at('PLUS') || this.at('MINUS')) {
      const op = this.next().type
      const right = this.parseMultiplicative()
      left = { type: 'binop', op, left, right }
    }
    return left
  }

  parseMultiplicative() {
    let left = this.parsePower()
    while (this.at('STAR') || this.at('SLASH')) {
      const op = this.next().type
      const right = this.parsePower()
      left = { type: 'binop', op, left, right }
    }
    return left
  }

  parsePower() {
    const left = this.parseUnary()
    if (this.at('CARET')) {
      this.next()
      const right = this.parsePower()
      return { type: 'binop', op: 'CARET', left, right }
    }
    return left
  }

  parseUnary() {
    if (this.at('PLUS') || this.at('MINUS')) {
      const op = this.next().type
      const operand = this.parseUnary()
      return { type: 'unary', op, operand }
    }
    return this.parseAtom()
  }

  parseAtom() {
    const t = this.peek()
    if (t.type === 'NUMBER') {
      this.next()
      return { type: 'number', value: t.value }
    }
    if (t.type === 'LP') {
      this.next()
      const inner = this.parseComparison()
      this.expect('RP')
      return { type: 'paren', inner }
    }
    if (t.type === 'IDENT') {
      this.next()
      const upper = t.value.toUpperCase()
      if (this.at('LP')) {
        this.next()
        const args = []
        if (!this.at('RP')) {
          args.push(this.parseComparison())
          while (this.at('COMMA')) {
            this.next()
            args.push(this.parseComparison())
          }
        }
        this.expect('RP')
        return { type: 'call', name: upper, args }
      }
      if (upper === 'TRUE') return { type: 'bool', value: true }
      if (upper === 'FALSE') return { type: 'bool', value: false }
      if (FUNCTION_NAMES.has(upper)) throw new ParseError()
      if (this.at('COLON')) {
        const save = this.pos
        this.next()
        if (this.at('IDENT')) {
          const t2 = this.next()
          return { type: 'range', from: upper, to: t2.value.toUpperCase() }
        }
        this.pos = save
      }
      return { type: 'address', token: upper }
    }
    throw new ParseError()
  }
}

/**
 * Parse a formula body (without the leading `=`). Returns { ok: true, ast }
 * on success or { ok: false } when the grammar does not accept the input.
 */
export function parseFormula(source) {
  const tokens = tokenize(source)
  if (tokens === null) return { ok: false }
  try {
    const ast = new Parser(tokens).parseProgram()
    return { ok: true, ast }
  } catch (e) {
    if (e instanceof ParseError) return { ok: false }
    throw e
  }
}
"}

