{"file_path":"src/sheet.js","content":"/**
 * Parsing of a whole sheet from standard input text into a map of declared
 * cells.
 */
import { parseAddressToken } from './address.js'

export class SheetError extends Error {
  constructor(line, message) {
    super(message)
    this.line = line
  }
}

/**
 * Parse sheet text into a Map from canonical address to
 * { content, col, row }. Throws SheetError on an invalid address or a
 * cell declared twice.
 */
export function parseSheet(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const cells = new Map()
  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const line = lines[i]

    let j = 0
    while (j < line.length && (line[j] === ' ' || line[j] === '\t')) j++
    const stripped = line.slice(j)
    if (stripped.length === 0) continue
    if (stripped[0] === '#') continue

    let k = 0
    while (k < stripped.length && stripped[k] !== ' ' && stripped[k] !== '\t') k++
    const addrToken = stripped.slice(0, k)

    let m = k
    while (m < stripped.length && (stripped[m] === ' ' || stripped[m] === '\t')) m++
    const content = stripped.slice(m)

    const parsed = parseAddressToken(addrToken)
    if (!parsed) {
      throw new SheetError(lineNo, `invalid cell address ${addrToken.toUpperCase()}`)
    }
    if (cells.has(parsed.address)) {
      throw new SheetError(lineNo, `cell ${parsed.address} is declared twice`)
    }
    cells.set(parsed.address, { content, col: parsed.col, row: parsed.row })
  }
  return cells
}
"}

