{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/** The command: `html`, `outline`, and `defs`, each over the document on standard input, and an optional definitions file. */

import { readFileSync } from 'node:fs'
import { BlockError, headings, parse, render, splitLines } from './block.js'
import { DefsError, loadDefinitionsFile } from './defs.js'

const MODES = ['html', 'outline', 'defs']
const USAGE = 'usage: cli.js html|outline|defs [<definitions>]'

/** Report one failure the way the specification words it, and stop. */
function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

const argv = process.argv.slice(2)
const mode = argv[0]
const definitionsPath = argv[1]
if (!MODES.includes(mode) || argv.length < 1 || argv.length > 2) fail(USAGE)

let fileDefinitions = new Map()
if (definitionsPath !== undefined) {
  try {
    fileDefinitions = loadDefinitionsFile(definitionsPath)
  } catch (error) {
    if (!(error instanceof DefsError)) throw error
    fail(error.message)
  }
}

let parsed
try {
  parsed = parse(splitLines(readFileSync(0, 'utf8')), fileDefinitions)
} catch (error) {
  if (!(error instanceof BlockError)) throw error
  fail(`line ${error.line}: ${error.message}`)
}

if (mode === 'html') {
  process.stdout.write(render(parsed.blocks, parsed.definitions))
} else if (mode === 'outline') {
  process.stdout.write(headings(parsed.blocks).map(one => `${one.level} ${one.text}\n`).join(''))
} else {
  const sorted = [...parsed.definitions.entries()].sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0))
  const lines = sorted.map(([label, definition]) => `${label} ${definition.url} ${definition.source}\n`)
  lines.push(`total ${sorted.length}\n`)
  process.stdout.write(lines.join(''))
}
"}

