import { SETTINGS } from './schema.js'

/** One refusal of an environment line, carrying the 1-based line and column it was read at. */
export class EnvError extends Error {
  /**
   * @param {number} line - the 1-based input line.
   * @param {number} column - the 1-based column of the raw line.
   * @param {string} message - the message the specification words, without the position.
   */
  constructor(line, column, message) {
    super(message)
    this.name = 'EnvError'
    this.line = line
    this.column = column
  }
}

/** Each schema key's environment name, e.g. `server.port` under `CONF_SERVER_PORT`. */
const BY_NAME = new Map(SETTINGS.map(declared => [`CONF_${declared.key.toUpperCase().replace(/\./g, '_')}`, declared.key]))

/** The 1-based column of the first non-space character of `raw`. */
function indent(raw) {
  return raw.length - raw.trimStart().length + 1
}

/**
 * Parse environment text into its settings, each carrying the position its value was written at.
 * @param {string} text - standard input's whole text.
 * @returns {{key: string, value: string, line: number, column: number}[]} each schema key's raw
 *   value, in the order the input writes them, with the value's own 1-based position.
 * @throws {EnvError} on the first line the grammar refuses.
 */
export function parseEnv(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  const entries = []
  const seen = new Set()
  for (const [index, raw] of lines.entries()) {
    const line = index + 1
    const trimmed = raw.trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue
    const column = indent(raw)
    const split = trimmed.indexOf('=')
    if (split === -1) throw new EnvError(line, column, 'expected NAME=VALUE')
    const name = trimmed.slice(0, split).trim()
    if (name === '') throw new EnvError(line, column, 'expected a variable name')
    if (!BY_NAME.has(name)) throw new EnvError(line, column, `unknown environment variable ${name}`)
    if (seen.has(name)) throw new EnvError(line, column, `${name} is set twice`)
    seen.add(name)
