    chunks.push(Buffer.from(buffer.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function parseArgs(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { mode: argv[0] }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    const workersStr = argv[1]
    if (!/^[1-9][0-9]*$/.test(workersStr)) {
      throw new CliError('workers must be a positive integer', 2)
    }
    return { mode: 'pack', workers: parseInt(workersStr, 10) }
  }
  throw new CliError(USAGE, 2)
}

function formatWaves(tasks, timings) {
  const byDepth = new Map()
  let maxDepth = -1
  for (const [name, timing] of timings) {
    if (!byDepth.has(timing.depth)) byDepth.set(timing.depth, [])
    byDepth.get(timing.depth).push(name)
    if (timing.depth > maxDepth) maxDepth = timing.depth
  }

  const lines = []
  for (let depth = 0; depth <= maxDepth; depth++) {
    const names = (byDepth.get(depth) || []).sort()
    lines.push(`wave ${depth}: ${names.join(' ')}`)
  }
  const total = timings.size > 0 ? Math.max(...[...timings.values()].map((t) => t.finish)) : 0
  lines.push(`total ${total}`)
  return lines.join('\n') + '\n'
}

function formatExplain(tasks, timings) {
  const lines = []
  for (const name of [...tasks.keys()].sort()) {
    const { start, finish, depth } = timings.get(name)
    lines.push(`${name} start=${start} finish=${finish} depth=${depth}`)
  }
  const total = timings.size > 0 ? Math.max(...[...timings.values()].map((t) => t.finish)) : 0
  lines.push(`total ${total}`)
  return lines.join('\n') + '\n'
}

function formatPack(result) {
  const lines = []
  for (let i = 0; i < result.workerLog.length; i++) {
    const entries = result.workerLog[i].map((e) => ` ${e.name}@${e.start}-${e.finish}`).join('')
    lines.push(`worker ${i}:${entries}`)
  }
  lines.push(`makespan ${result.makespan}`)
  return lines.join('\n') + '\n'
}

function main() {
  const argv = process.argv.slice(2)
  const args = parseArgs(argv)

  const input = readStdin()
  const tasks = parseGraph(input)
  detectCycle(tasks)

  let output
  if (args.mode === 'waves') {
    output = formatWaves(tasks, computeTimings(tasks))
  } else if (args.mode === 'explain') {
    output = formatExplain(tasks, computeTimings(tasks))
  } else {
    output = formatPack(packWorkers(tasks, args.workers))
  }

  process.stdout.write(output)
}

try {
  main()
} catch (err) {
  if (err instanceof CliError) {
    process.stderr.write(`error: ${err.message}\n`)
    process.exit(err.exitCode)
  }
  throw err
}
"}

