import { makeTable, makeArrayOfTables } from './nodes.js'
import { Scanner, assignInto } from './scanner.js'

/** Walks `names` under `startNode` (as `assignInto` does) without assigning
 * anything, returning the table reached after all but the last segment.
 * Used by header processing, which always walks from the document root. */
function walkIntermediate(startNode, names, lineNumber, prefix) {
  let node = startNode
  for (let k = 0; k < names.length - 1; k++) {
    const key = names[k]
    let child = node.map.get(key)
    if (child === undefined) {
      child = makeTable()
      node.map.set(key, child)
    } else if (child.type === 'table') {
      // descend
    } else if (child.type === 'array-of-tables') {
      child = child.items[child.items.length - 1]
    } else {
      const at = prefix.concat(names.slice(0, k + 1))
      throw new ParseError(lineNumber, `${at.join('.')} is not a table`)
    }
    node = child
  }
  return node
}

function processTableHeader(root, names, lineNumber) {
  const parent = walkIntermediate(root, names, lineNumber, [])
  const lastKey = names[names.length - 1]
  const existing = parent.map.get(lastKey)
  if (existing === undefined) {
    const table = makeTable()
    table.headerDeclared = true
    parent.map.set(lastKey, table)
    return { table, path: names }
  }
  if (existing.type !== 'table') {
