{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */

import { mergeParts } from './diff3.js'

const MODES = ['merge', 'merge2', 'regions']

/**
 * Splits stdin text into the three documents it holds, dropping the empty
 * tail a trailing newline leaves. Throws when the input does not separate
 * into exactly three parts on lines that are exactly `%%%`.
 */
function parseInput(text) {
  let lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines = lines.slice(0, -1)

  const docs = [[]]
  for (const line of lines) {
    if (line === '%%%') docs.push([])
    else docs[docs.length - 1].push(line)
  }
  if (docs.length !== 3) throw new Error('expected three parts separated by %%%')
  return docs
}

function readStdin() {
  const chunks = []
  const fd = 0
  const fs = require('node:fs')
  const buffer = Buffer.alloc(65536)
  while (true) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buffer, 0, buffer.length, null)
    } catch (error) {
      if (error.code === 'EAGAIN') continue
      if (error.code === 'EOF') break
      throw error
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buffer.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function writeConflict(out, region, includeBase) {
  out.push('<<<<<<< mine')
  out.push(...region.mine)
  if (includeBase) {
    out.push('||||||| base')
    out.push(...region.base)
  }
  out.push('=======')
  out.push(...region.theirs)
  out.push('>>>>>>> theirs')
}

function runMerge(parts, includeBase) {
  const out = []
  let conflict = false
  for (const part of parts) {
    if (part.type === 'stable') {
      out.push(...part.lines)
    } else if (part.region.kind === 'conflict') {
      conflict = true
      writeConflict(out, part.region, includeBase)
    } else {
      out.push(...part.region.lines)
    }
  }
  return { text: out.length > 0 ? `${out.join('\n')}\n` : '', conflict }
}

function runRegions(parts) {
  const out = []
  let conflict = false
  for (const part of parts) {
    if (part.type === 'stable') {
      if (part.lines.length > 0) out.push(`stable ${part.lines.length}`)
    } else if (part.region.kind === 'conflict') {
      conflict = true
      out.push(`conflict mine=${part.region.mine.length} base=${part.region.base.length} theirs=${part.region.theirs.length}`)
    } else {
      out.push(`${part.region.kind} ${part.region.lines.length}`)
    }
  }
  return { text: out.length > 0 ? `${out.join('\n')}\n` : '', conflict }
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || !MODES.includes(mode)) {
    process.stderr.write('error: usage: cli.js merge|merge2|regions\n')
    process.exit(2)
  }

  const input = readStdin()
  let mine, base, theirs
  try {
    ;[mine, base, theirs] = parseInput(input)
  } catch (error) {
    process.stderr.write(`error: ${error.message}\n`)
    process.exit(2)
    return
  }

  const parts = mergeParts(mine, base, theirs)
  const result = mode === 'regions' ? runRegions(parts) : runMerge(parts, mode === 'merge')

  process.stdout.write(result.text)
  process.exit(result.conflict ? 1 : 0)
}

main()
"}

