{"file_path":"src/policies.js","content":"/**
 * The two policy kinds a limiter file can declare. Both track one
 * independent state per key, created lazily the first time that key
 * reaches the policy.
 */

/**
 * A token bucket. Tokens are tracked scaled by `per` (as `tokens * per`)
 * so that the fractional refill accumulated between periods is exact
 * integer arithmetic instead of floating point.
 */
export class TokenBucket {
  constructor(capacity, refill, per) {
    this.capacity = capacity
    this.refill = refill
    this.per = per
    this.cap = capacity * per
    this.states = new Map()
  }

  #state(key) {
    let state = this.states.get(key)
    if (state === undefined) {
      state = { scaled: this.cap, lastTick: null }
      this.states.set(key, state)
    }
    return state
  }

  advance(key, tick) {
    const state = this.#state(key)
    if (state.lastTick !== null) {
      const elapsed = tick - state.lastTick
      const scaled = state.scaled + this.refill * elapsed
      state.scaled = scaled > this.cap ? this.cap : scaled
    }
    state.lastTick = tick
  }

  wouldAllow(key) {
    return this.#state(key).scaled >= this.per
  }

  record(key) {
    this.#state(key).scaled -= this.per
  }
}

/** A sliding window. Remembers the ticks of the requests it recorded. */
export class SlidingWindow {
  constructor(limit, span) {
    this.limit = limit
    this.span = span
    this.states = new Map()
  }

  #state(key) {
    let state = this.states.get(key)
    if (state === undefined) {
      state = { ticks: [] }
      this.states.set(key, state)
    }
    return state
  }

  advance(key, tick) {
    const state = this.#state(key)
    const threshold = tick - this.span
    let cut = 0
    while (cut < state.ticks.length && state.ticks[cut] <= threshold) cut++
    if (cut > 0) state.ticks.splice(0, cut)
  }

  wouldAllow(key) {
    return BigInt(this.#state(key).ticks.length) < this.limit
  }

  record(key, tick) {
    this.#state(key).ticks.push(tick)
  }
}
"}

