{"file_path":"src/parse.js","content":"/**
 * Parses a limiter file into declared policies, routes and events, or
 * throws a `LineError` naming the first line that fails.
 */
import { TokenBucket, SlidingWindow } from './policies.js'

const NAME_RE = /^[A-Za-z0-9_./:-]+$/
const UINT_RE = /^(0|[1-9][0-9]*)$/

export class LineError extends Error {
  constructor(line, reason) {
    super(`line ${line}: ${reason}`)
    this.line = line
    this.reason = reason
  }
}

function parseField(token, fieldName, least) {
  if (UINT_RE.test(token)) {
    const value = BigInt(token)
    if (value >= least) return value
  }
  throw new Error(`${fieldName} must be an integer of at least ${least}`)
}

/**
 * @param {string} text raw standard input
 * @returns {{ policies: Map<string, object>, routes: Array<{prefix: string, policies: string[]}>, events: Array<{tick: bigint, key: string}> }}
 */
export function parseLimiterFile(text) {
  const rawLines = text.split('\n')
  if (rawLines.length > 0 && rawLines[rawLines.length - 1] === '') rawLines.pop()

  const policies = new Map()
  const routes = []
  const routesByPrefix = new Map()
  const events = []
  let eventSeen = false
  let lastTick = null

  for (let i = 0; i < rawLines.length; i++) {
    const lineNumber = i + 1
    const line = rawLines[i].trim()
    if (line === '' || line.startsWith('#')) continue

    try {
      const tokens = line.split(/\s+/)
      const directive = tokens[0]
      const rest = tokens.slice(1)

      if (directive === 'event') {
        if (rest.length !== 2) throw new Error('expected event <tick> <key>')
        const tick = parseField(rest[0], 'tick', 0n)
        if (lastTick !== null && tick < lastTick) {
          throw new Error(`tick ${tick} is before tick ${lastTick}`)
        }
        const key = rest[1]
        if (!NAME_RE.test(key)) throw new Error(`invalid key ${key}`)
        events.push({ tick, key })
        eventSeen = true
        lastTick = tick
        continue
      }

      if (directive === 'bucket' || directive === 'window' || directive === 'route') {
        if (eventSeen) throw new Error('declarations must come before the first event')
      } else {
        throw new Error(`unknown directive ${directive}`)
      }

      if (directive === 'bucket') {
        if (rest.length !== 4) throw new Error('expected bucket <name> <capacity> <refill> <per>')
        const [name, capacityTok, refillTok, perTok] = rest
        if (!NAME_RE.test(name)) throw new Error(`invalid policy name ${name}`)
        if (policies.has(name)) throw new Error(`policy ${name} is declared twice`)
        const capacity = parseField(capacityTok, 'capacity', 1n)
        const refill = parseField(refillTok, 'refill', 0n)
        const per = parseField(perTok, 'per', 1n)
        policies.set(name, new TokenBucket(capacity, refill, per))
        continue
      }

      if (directive === 'window') {
        if (rest.length !== 3) throw new Error('expected window <name> <limit> <span>')
        const [name, limitTok, spanTok] = rest
        if (!NAME_RE.test(name)) throw new Error(`invalid policy name ${name}`)
        if (policies.has(name)) throw new Error(`policy ${name} is declared twice`)
        const limit = parseField(limitTok, 'limit', 0n)
        const span = parseField(spanTok, 'span', 1n)
        policies.set(name, new SlidingWindow(limit, span))
        continue
      }

      // directive === 'route'
      if (rest.length < 2) throw new Error('expected route <prefix> <policy>...')
      const [prefix, ...policyNames] = rest
      if (!NAME_RE.test(prefix)) throw new Error(`invalid route prefix ${prefix}`)
      if (routesByPrefix.has(prefix)) throw new Error(`prefix ${prefix} is routed twice`)
      for (const name of policyNames) {
        if (!policies.has(name)) throw new Error(`unknown policy ${name}`)
      }
      const route = { prefix, policies: policyNames }
      routes.push(route)
      routesByPrefix.set(prefix, route)
    } catch (err) {
      throw new LineError(lineNumber, err.message)
    }
  }

  return { policies, routes, events }
}
"}

