{"file_path":"src/simulate.js","content":"/**
 * Replays a parsed limiter file's events against its routes and
 * policies, returning one verdict per event in log order.
 */

function findRoute(routes, key) {
  let best = null
  for (const route of routes) {
    if (key.startsWith(route.prefix)) {
      if (best === null || route.prefix.length > best.prefix.length) best = route
    }
  }
  return best
}

/**
 * @returns {Array<{ tick: bigint, key: string, allowed: boolean, deniedBy: string | null }>}
 */
export function simulate({ policies, routes, events }) {
  const results = []

  for (const { tick, key } of events) {
    const route = findRoute(routes, key)
    const policyNames = route === null ? [] : route.policies

    for (const name of policyNames) {
      policies.get(name).advance(key, tick)
    }

    let deniedBy = null
    for (const name of policyNames) {
      if (!policies.get(name).wouldAllow(key)) {
        deniedBy = name
        break
      }
    }

    if (deniedBy === null) {
      for (const name of policyNames) {
        policies.get(name).record(key, tick)
      }
    }

    results.push({ tick, key, allowed: deniedBy === null, deniedBy })
  }

  return results
}
"}

