{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */
import { parseLimiterFile, LineError } from './parse.js'
import { simulate } from './simulate.js'

function readStdin() {
  const chunks = []
  const fd = 0
  const buffer = Buffer.alloc(65536)
  const fs = require('node:fs')
  while (true) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buffer, 0, buffer.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buffer.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function formatReplay(results) {
  const lines = []
  for (const { tick, key, allowed, deniedBy } of results) {
    lines.push(allowed ? `${tick} ${key} allow` : `${tick} ${key} deny ${deniedBy}`)
  }
  return lines.map((line) => line + '\n').join('')
}

function formatSummary(results) {
  const perKey = new Map()
  let totalAllowed = 0
  let totalDenied = 0

  for (const { key, allowed } of results) {
    let counts = perKey.get(key)
    if (counts === undefined) {
      counts = { allowed: 0, denied: 0 }
      perKey.set(key, counts)
    }
    if (allowed) {
      counts.allowed++
      totalAllowed++
    } else {
      counts.denied++
      totalDenied++
    }
  }

  const keys = [...perKey.keys()].sort()
  const lines = keys.map((key) => {
    const counts = perKey.get(key)
    return `${key} allowed=${counts.allowed} denied=${counts.denied}\n`
  })
  lines.push(`total allowed=${totalAllowed} denied=${totalDenied}\n`)
  return lines.join('')
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'replay' && mode !== 'summary')) {
    process.stderr.write('error: usage: cli.js replay|summary\n')
    process.exit(2)
  }

  const text = readStdin()

  let parsed
  try {
    parsed = parseLimiterFile(text)
  } catch (err) {
    if (err instanceof LineError) {
      process.stderr.write(`error: ${err.message}\n`)
      process.exit(2)
    }
    throw err
  }

  const results = simulate(parsed)
  const output = mode === 'replay' ? formatReplay(results) : formatSummary(results)
  process.stdout.write(output)
  process.exit(0)
}

main()
"}

