{"file_path":"src/layer.js","content":"/** Stacking layers: the last layer that sets a key wins, one key at a time. */

/**
 * Merge named layers, later over earlier.
 * @param {readonly {name: string, path: string, values: Map<string, {text: string, line: number, column: number}>}[]} layers -
 *   the layers, weakest first.
 * @returns {Map<string, {text: string, line: number, column: number, path: string, layer: string}>}
 *   each key's winning text, its written position, and the name and path of the layer that set it.
 */
export function merge(layers) {
  const merged = new Map()
  for (const layer of layers) {
    for (const [key, entry] of layer.values) {
      merged.set(key, { text: entry.text, line: entry.line, column: entry.column, path: layer.path, layer: layer.name })
    }
  }
  return merged
}
"}

